# -*- coding: utf-8 -*-
"""Begriffe zum deutschen Patentrecht (PatG, PatV, IntPatÜG, PatKostG). Felder wie knowledge/concepts.py;
`norms` in der Zitierweise `§ 3 Abs. 1 PatG`, `§ 9 PatV`, `Art. II § 6 IntPatÜG`, `§ 6 PatKostG`; `ipwiki` bleibt leer."""


def c(id, label, kategorie, definition, erlaeuterung, norms=(), cases=(), related=()):
    return dict(id=id, label=label, kategorie=kategorie, definition=definition, erlaeuterung=erlaeuterung,
                norms=list(norms), cases=list(cases), ipwiki=[], related=list(related), quellen=[])


P, S, W, A, E, N, V, K, I = ("Patent: Patentfähigkeit", "Patent: Schutzbereich und Auslegung", "Patent: Wirkung, Verletzung, Schranken",
                             "Patent: Anmeldung und Erteilung", "Patent: Einspruch und Beschränkung", "Patent: Nichtigkeit und Zwangslizenz",
                             "Patent: Verfahren, Fristen, Rechtsmittel", "Patent: Kosten und Gebühren (PatKostG)", "Patent: Europäische und internationale Anmeldung (IntPatÜG)")

CONCEPTS = [
    # ------------------------------------------------------------------ Patentfähigkeit
    c("pat_erfindung", "Erfindung und Patentfähigkeit (§ 1 PatG)", P,
      "Patente werden für Erfindungen auf allen Gebieten der Technik erteilt, die neu sind, auf erfinderischer Tätigkeit beruhen und gewerblich anwendbar sind (§ 1 Abs. 1 PatG). Eine Erfindung ist eine Lehre zum planmäßigen Handeln unter Einsatz beherrschbarer Naturkräfte zur Erreichung eines kausal übersehbaren Erfolgs (Technizität).",
      "Prüfungsreihenfolge: (1) technische Erfindung, (2) kein Ausschluss nach § 1 Abs. 3, 4, § 1a, § 2, § 2a, (3) Neuheit § 3, (4) erfinderische Tätigkeit § 4, (5) gewerbliche Anwendbarkeit § 5. Parallel Art. 52 bis 57 EPÜ; für europäische Patente mit Wirkung für Deutschland gelten dieselben Kriterien über Art. II § 6 IntPatÜG.",
      norms=["§ 1 Abs. 1 PatG", "§ 3 PatG", "§ 4 PatG", "§ 5 PatG"], cases=["pat_bgh_steuerungseinrichtung"], related=["pat_technizitaet", "pat_neuheit", "pat_erfinderische_taetigkeit", "pat_gewerbliche_anwendbarkeit"]),
    c("pat_technizitaet", "Technizität", P,
      "Technisch ist eine Lehre, die den Einsatz beherrschbarer Naturkräfte zur unmittelbaren Herbeiführung eines kausal übersehbaren Erfolgs vorsieht; sie ist Voraussetzung jeder Erfindung (§ 1 Abs. 1 PatG) und wird vom Negativkatalog des § 1 Abs. 3 PatG nur „als solche“ ausgeschlossen (§ 1 Abs. 4 PatG).",
      "Der BGH prüft bei Datenverarbeitung zweistufig: Technizität liegt schon vor, wenn ein Teilaspekt technisch ist (Ablauf auf einer Datenverarbeitungsanlage genügt); der Ausschluss als Programm „als solches“ greift nur, wenn kein konkretes technisches Problem mit technischen Mitteln gelöst wird (Webseitenanzeige, Dynamische Dokumentengenerierung). Nichttechnische Merkmale tragen die erfinderische Tätigkeit nicht.",
      norms=["§ 1 Abs. 1 PatG", "§ 1 Abs. 3 PatG", "§ 1 Abs. 4 PatG"], cases=["pat_bgh_steuerungseinrichtung", "pat_bgh_webseitenanzeige", "pat_bgh_rezeptortyrosinkinase"], related=["pat_programme", "pat_erfindung"]),
    c("pat_programme", "Computerprogramme und Geschäftsmethoden (§ 1 Abs. 3 Nr. 3 PatG)", P,
      "Programme für Datenverarbeitungsanlagen, Regeln für geistige Tätigkeiten und Geschäftsmethoden sind als solche keine Erfindungen (§ 1 Abs. 3 Nr. 3, Abs. 4 PatG). Patentfähig ist eine programmbezogene Lehre, wenn sie ein konkretes technisches Problem mit technischen Mitteln löst.",
      "Technische Mittel: Modifikation von Gerätekomponenten, Ablauf, der durch technische Gegebenheiten außerhalb der Datenverarbeitung bestimmt ist, oder Berücksichtigung der Arbeitsweise der Anlage. Reine Datenverarbeitung, Präsentation von Informationen oder betriebswirtschaftliche Vorgaben bleiben außer Betracht (Webseitenanzeige). Parallel: EPA „Comvik“-Ansatz.",
      norms=["§ 1 Abs. 3 Nr. 3 PatG", "§ 1 Abs. 4 PatG"], cases=["pat_bgh_dynamische_dokumentengenerierung", "pat_bgh_webseitenanzeige", "pat_bgh_steuerungseinrichtung"], related=["pat_technizitaet", "pat_erfinderische_taetigkeit"]),
    c("pat_biotech", "Biotechnologische Erfindungen (§§ 1a, 2, 2a PatG)", P,
      "Der menschliche Körper und die bloße Entdeckung seiner Bestandteile einschließlich Gensequenzen sind nicht patentfähig (§ 1a Abs. 1 PatG); isolierte Bestandteile mit angegebener Funktion sind es (§ 1a Abs. 2, 3). Ausgeschlossen sind Verfahren gegen die öffentliche Ordnung (§ 2 PatG), Pflanzensorten, Tierrassen und im Wesentlichen biologische Züchtungsverfahren (§ 2a PatG).",
      "Umsetzung der Biopatentrichtlinie 98/44/EG. Zweckbindung bei menschlichen Gensequenzen (§ 1a Abs. 4). Pflanzen und Tiere sind patentfähig, wenn die Ausführung nicht auf eine Sorte beschränkt ist (§ 2a Abs. 2 Nr. 1). Reichweite des Schutzes bei biologischem Material: §§ 9a bis 9c PatG (Landwirteprivileg).",
      norms=["§ 1a PatG", "§ 2 PatG", "§ 2a PatG", "§ 9a PatG", "§ 9c PatG"], cases=["pat_bgh_rezeptortyrosinkinase"], related=["pat_erfindung", "pat_therapeutische_verfahren"]),
    c("pat_therapeutische_verfahren", "Therapeutische, chirurgische und diagnostische Verfahren", P,
      "Verfahren zur chirurgischen oder therapeutischen Behandlung des menschlichen oder tierischen Körpers und Diagnostizierverfahren am Körper sind vom Patentschutz ausgeschlossen (§ 2a Abs. 1 Nr. 2 PatG); Erzeugnisse zur Anwendung in diesen Verfahren sind patentfähig.",
      "Bis 2005 als fehlende gewerbliche Anwendbarkeit (§ 5 Abs. 2 a.F.) konstruiert, seither Patentierungsausschluss. Die Verabreichung eines Arzneimittels ist ein therapeutisches Verfahren (Carvedilol II); Schutz nur über zweckgebundenen Stoffschutz (§ 3 Abs. 3, 4) oder sinnfällige Herrichtung.",
      norms=["§ 2a Abs. 1 Nr. 2 PatG", "§ 5 Abs. 2 PatG", "§ 3 Abs. 4 PatG"], cases=["pat_bgh_carvedilol_ii"], related=["pat_zweite_indikation", "pat_gewerbliche_anwendbarkeit"]),
    c("pat_neuheit", "Neuheit und Stand der Technik (§ 3 PatG)", P,
      "Eine Erfindung gilt als neu, wenn sie nicht zum Stand der Technik gehört; dieser umfasst alle Kenntnisse, die vor dem maßgeblichen Tag durch schriftliche oder mündliche Beschreibung, Benutzung oder sonst der Öffentlichkeit zugänglich gemacht worden sind (§ 3 Abs. 1 PatG). Ältere, erst später veröffentlichte Anmeldungen zählen nur für die Neuheit (§ 3 Abs. 2 PatG).",
      "Absoluter, weltweiter Neuheitsbegriff; Einzelvergleich mit jeder Entgegenhaltung; neuheitsschädlich ist nur, was unmittelbar und eindeutig offenbart ist, einschließlich des selbstverständlich Mitgelesenen, nicht aber Ergänzungen aus dem Fachwissen (Olanzapin). Keine allgemeine Neuheitsschonfrist; Ausnahmen § 3 Abs. 5 PatG (Missbrauch, Ausstellung). Gebrauchsmuster: relativer Neuheitsbegriff mit Schonfrist (§ 3 GebrMG).",
      norms=["§ 3 Abs. 1 PatG", "§ 3 Abs. 2 PatG", "§ 3 Abs. 5 PatG"], cases=["pat_bgh_olanzapin", "pat_bgh_glasfasern", "pat_bgh_hohlfaserdialysator"], related=["pat_offenbarung", "pat_erfinderische_taetigkeit", "pat_zweite_indikation"]),
    c("pat_offenbarung", "Offenbarung (unmittelbar und eindeutig)", P,
      "Offenbart ist, was der Fachmann einer Quelle als technische Information unmittelbar und eindeutig entnimmt, einschließlich dessen, was für ihn selbstverständlich ist und „mitgelesen“ wird; nicht offenbart ist, was er erst durch eigene Überlegungen aus seinem Fachwissen ergänzt.",
      "Einheitlicher Offenbarungsbegriff für Neuheit (§ 3), unzulässige Erweiterung (§ 21 Abs. 1 Nr. 4, § 38), Priorität (§§ 40, 41) und Ausführbarkeit. Eine allgemeine Formel offenbart die Einzelverbindungen nicht (Olanzapin); Zahlenbereiche offenbaren nicht jeden Einzelwert. Weglassen eines Merkmals ist nicht Ersetzen (Überbrücktes Netzwerk).",
      norms=["§ 3 Abs. 1 PatG", "§ 38 PatG", "§ 21 Abs. 1 Nr. 4 PatG"], cases=["pat_bgh_olanzapin", "pat_bgh_rotorelemente", "pat_bgh_kommunikationskanal", "pat_bgh_ueberbruecktes_netzwerk"], related=["pat_neuheit", "pat_unzulaessige_erweiterung", "pat_prioritaet"]),
    c("pat_zweite_indikation", "Zweckgebundener Stoffschutz und zweite medizinische Indikation", P,
      "Ein bekannter Stoff kann für eine erste (§ 3 Abs. 3 PatG) oder eine weitere spezifische Anwendung in einem therapeutischen Verfahren (§ 3 Abs. 4 PatG) als neu geschützt werden, wenn die Anwendung nicht zum Stand der Technik gehört (zweckgebundener Stoffschutz).",
      "Anspruchsform: „Stoff X zur Verwendung bei der Behandlung von Y“; früher „Verwendung von X zur Herstellung eines Arzneimittels“ (Schweizer Anspruch). Verletzung durch sinnfällige Herrichtung (Beipackzettel, Dosierung). Abgrenzung zum ausgeschlossenen Behandlungsverfahren (Carvedilol II).",
      norms=["§ 3 Abs. 3 PatG", "§ 3 Abs. 4 PatG"], cases=["pat_bgh_carvedilol_ii", "pat_bpatg_imidazolinpyrimidon"], related=["pat_neuheit", "pat_therapeutische_verfahren"]),
    c("pat_erfinderische_taetigkeit", "Erfinderische Tätigkeit (§ 4 PatG)", P,
      "Eine Erfindung beruht auf erfinderischer Tätigkeit, wenn sie sich für den Fachmann nicht in naheliegender Weise aus dem Stand der Technik ergibt (§ 4 S. 1 PatG); ältere nachveröffentlichte Anmeldungen bleiben außer Betracht (§ 4 S. 2 PatG).",
      "Der BGH fragt, ob der Fachmann Veranlassung hatte, den Stand der Technik in Richtung der Erfindung weiterzuentwickeln (Fischbissanzeiger, Kinderbett); allgemeines Fachwissen allein begründet keinen Anlass (Airbag-Auslösesteuerung), generelle Lösungsmittel des Maschinenbaus schon (Farbversorgungssystem). Keine Zerlegung in Teilaufgaben (Papiermaschinengewebe), keine rückschauende Betrachtung. Der Aufgabe-Lösungs-Ansatz des EPA ist Hilfsmittel.",
      norms=["§ 4 PatG"], cases=["pat_bgh_fischbissanzeiger", "pat_bgh_airbag_ausloesesteuerung", "pat_bgh_kinderbett", "pat_bgh_papiermaschinengewebe", "pat_bgh_einteilige_oese", "pat_bgh_farbversorgungssystem", "pat_bgh_gleitlagerueberwachung"], related=["pat_fachmann", "pat_aufgabe_loesung", "pat_neuheit"]),
    c("pat_fachmann", "Fachmann (Durchschnittsfachmann)", P,
      "Der Fachmann ist eine fiktive Person mit den durchschnittlichen Kenntnissen und Fähigkeiten auf dem technischen Gebiet der Erfindung am Prioritätstag; er ist Maßstab für Auslegung, Neuheit, erfinderische Tätigkeit, Ausführbarkeit und Äquivalenz.",
      "Bestimmung nach dem Problem, das die Erfindung löst: Konstrukteur mit Erfahrung im Gerätebau, nicht der Anwender (Fischbissanzeiger); bei interdisziplinären Aufgaben ein Team. Der Fachmann hat Fachwissen und Routine, aber keine Erfindungsgabe.",
      norms=["§ 4 PatG", "§ 14 PatG"], cases=["pat_bgh_fischbissanzeiger", "pat_bgh_airbag_ausloesesteuerung"], related=["pat_erfinderische_taetigkeit", "pat_auslegung"]),
    c("pat_aufgabe_loesung", "Aufgabe und Lösung (technisches Problem)", P,
      "Das technische Problem (Aufgabe) ist objektiv aus dem zu bestimmen, was die Erfindung gegenüber dem Stand der Technik tatsächlich leistet; es darf keine Lösungselemente enthalten und ist nicht an die in der Patentschrift formulierte Aufgabe gebunden.",
      "Die Beschreibung muss die Aufgabe angeben (§ 10 Abs. 2 PatV); für § 4 ist aber die objektive Aufgabe maßgeblich. Eine Aufgabe, die auf die Lösung hinweist, führt zur unzulässigen Rückschau. Zerlegung in Teilaufgaben ist unzulässig (Papiermaschinengewebe).",
      norms=["§ 4 PatG", "§ 10 PatV"], cases=["pat_bgh_papiermaschinengewebe"], related=["pat_erfinderische_taetigkeit", "pat_beschreibung"]),
    c("pat_gewerbliche_anwendbarkeit", "Gewerbliche Anwendbarkeit (§ 5 PatG)", P,
      "Eine Erfindung ist gewerblich anwendbar, wenn ihr Gegenstand auf irgendeinem gewerblichen Gebiet einschließlich der Landwirtschaft hergestellt oder benutzt werden kann (§ 5 Abs. 1 PatG).",
      "Fehlt fast nie; Bedeutung nur bei fehlender Wiederholbarkeit oder bei Lehren ohne technischen Nutzen. Die früher hier verortete Ausnahme für Behandlungsverfahren steht seit 2005 in § 2a Abs. 1 Nr. 2 PatG.",
      norms=["§ 5 PatG"], cases=[], related=["pat_erfindung", "pat_therapeutische_verfahren"]),
    c("pat_ausfuehrbarkeit", "Ausführbarkeit (deutliche und vollständige Offenbarung)", P,
      "Die Anmeldung muss die Erfindung so deutlich und vollständig offenbaren, dass ein Fachmann sie ausführen kann (§ 34 Abs. 4 PatG); fehlende Ausführbarkeit ist Widerrufs- und Nichtigkeitsgrund (§ 21 Abs. 1 Nr. 2, § 22 PatG, Art. II § 6 Abs. 1 Nr. 2 IntPatÜG).",
      "Ausführbar ist die Lehre, wenn der Fachmann sie ohne unzumutbaren Aufwand und ohne eigene erfinderische Leistung nacharbeiten kann; ein Ausführungsweg genügt, wenn er die Breite des Anspruchs abdeckt (Thermoplastische Zusammensetzung). Bei neuen Stoffen ist die medizinische Verwendung durch den Stoffschutz unterlegt (BPatG Imidazolinpyrimidon). Abzugrenzen von der Klarheit (kein Nichtigkeitsgrund).",
      norms=["§ 34 Abs. 4 PatG", "§ 21 Abs. 1 Nr. 2 PatG", "Art. II § 6 Abs. 1 Nr. 2 IntPatÜG"], cases=["pat_bgh_thermoplastische_zusammensetzung", "pat_bpatg_imidazolinpyrimidon"], related=["pat_offenbarung", "pat_nichtigkeitsgruende", "pat_widerrufsgruende"]),
    # ------------------------------------------------------------------ Schutzbereich
    c("pat_schutzbereich", "Schutzbereich (§ 14 PatG)", S,
      "Der Schutzbereich des Patents wird durch die Patentansprüche bestimmt; Beschreibung und Zeichnungen sind zur Auslegung heranzuziehen (§ 14 PatG, Art. 69 EPÜ mit Auslegungsprotokoll). Er umfasst die wortsinngemäße Benutzung und den Äquivalenzbereich.",
      "Die Ansprüche sind Grenze und Grundlage zugleich (weder wörtliche Auslegung noch bloße Richtlinie). Vorgänge im Erteilungsverfahren sind grundsätzlich unbeachtlich (Kunststoffrohrteil). Zahlen- und Maßangaben begrenzen mit (Schneidmesser I). Die Zusammenfassung dient nicht der Auslegung (§ 36 Abs. 2 PatG).",
      norms=["§ 14 PatG", "§ 9 PatV"], cases=["pat_bgh_schneidmesser_i", "pat_bgh_kunststoffrohrteil", "pat_bgh_okklusionsvorrichtung"], related=["pat_auslegung", "pat_aequivalenz", "pat_patentanspruch"]),
    c("pat_auslegung", "Auslegung des Patentanspruchs", S,
      "Der Patentanspruch ist aus der Sicht des Fachmanns nach seinem technischen Sinngehalt auszulegen; Beschreibung und Zeichnungen erläutern die Merkmale und deren Funktion im Gesamtzusammenhang (funktionsorientierte Auslegung). Die Patentschrift ist ihr eigenes Lexikon.",
      "Ausführungsbeispiele beschränken den allgemein gefassten Anspruch nicht (Bodenseitige Vereinzelungseinrichtung); bei Widersprüchen gehen die Ansprüche vor (Okklusionsvorrichtung); die Abgrenzung vom beschriebenen Stand der Technik ist zu berücksichtigen (Scheinwerferbelüftungssystem). Das Verletzungsgericht legt selbständig aus (Kreuzgestänge). Zweck- und Funktionsangaben: Bildunterstützung, Referenzkontur.",
      norms=["§ 14 PatG"], cases=["pat_bgh_drehzahlermittlung", "pat_bgh_bodenseitige_vereinzelungseinrichtung", "pat_bgh_okklusionsvorrichtung", "pat_bgh_scheinwerferbelueftungssystem", "pat_bgh_kreuzgestaenge", "pat_bgh_kunststoffrohrteil"], related=["pat_schutzbereich", "pat_zweckangabe", "pat_fachmann"]),
    c("pat_zweckangabe", "Zweck-, Wirkungs- und Funktionsangaben", S,
      "Zweck-, Wirkungs- und Funktionsangaben im Anspruch beschränken den Gegenstand nicht auf den genannten Zweck, können ihn aber mittelbar definieren: Die Vorrichtung muss so ausgebildet sein, dass sie die angegebene Funktion erfüllen kann.",
      "Bei Erzeugnisansprüchen führt die Zweckangabe zur Eignung („geeignet zu“), bei Verfahrensansprüchen ist durch Auslegung zu klären, ob die Angabe das Verfahren definiert oder nur beispielhaft ist (Referenzkontur). Bei der zweiten medizinischen Indikation ist der Zweck dagegen schutzbegründend.",
      norms=["§ 14 PatG", "§ 9 PatV"], cases=["pat_bgh_bildunterstuetzung_katheternavigation", "pat_bgh_referenzkontur"], related=["pat_auslegung", "pat_zweite_indikation"]),
    c("pat_aequivalenz", "Äquivalente Patentverletzung", S,
      "Eine vom Wortsinn abweichende Ausführung verletzt das Patent äquivalent, wenn sie das Problem mit gleichwirkenden Mitteln löst (Gleichwirkung), der Fachmann die abgewandelten Mittel aufgrund seiner Fachkenntnisse als gleichwirkend auffinden konnte (Auffindbarkeit) und seine Überlegungen am Sinngehalt des Anspruchs orientiert waren (Gleichwertigkeit): die drei Schneidmesser-Fragen.",
      "Gleichwirkung verlangt gerade die Wirkung des ersetzten Merkmals (Palettenbehälter III). Auswahlentscheidung: Offenbart die Beschreibung mehrere Wege und beansprucht nur einen, ist der andere nicht gleichwertig (Okklusionsvorrichtung, Diglycidverbindung); Ausnahmen und Grenzen in Pemetrexed. Orientierung am Anspruch: V-förmige Führungsanordnung. Formstein-Einwand: keine Äquivalenz, wenn die Ausführung zum Stand der Technik gehört oder ihm nahegelegt war.",
      norms=["§ 14 PatG"], cases=["pat_bgh_schneidmesser_i", "pat_bgh_custodiol_ii", "pat_bgh_okklusionsvorrichtung", "pat_bgh_diglycidverbindung", "pat_bgh_pemetrexed", "pat_bgh_v_foermige_fuehrungsanordnung", "pat_bgh_palettenbehaelter_iii"], related=["pat_schutzbereich", "pat_auslegung", "pat_verletzung"]),
    c("pat_patentanspruch", "Patentanspruch (§ 9 PatV)", S,
      "Der Patentanspruch gibt an, was unter Schutz gestellt werden soll (§ 34 Abs. 3 Nr. 3 PatG); er ist ein- oder zweiteilig (Oberbegriff mit dem Stand der Technik, kennzeichnender Teil mit der Erfindung) zu fassen und darf nicht auf die Beschreibung verweisen (§ 9 PatV).",
      "Anspruchskategorien: Erzeugnis, Verfahren, Verwendung, Vorrichtung; nebengeordnete Ansprüche und Unteransprüche (§ 9 Abs. 3, 4 PatV). Der Anspruch bestimmt den Schutzbereich (§ 14 PatG); die Merkmalsgliederung ist die Arbeitsgrundlage jeder Verletzungs- und Rechtsbestandsprüfung.",
      norms=["§ 9 PatV", "§ 34 Abs. 3 Nr. 3 PatG", "§ 14 PatG"], cases=[], related=["pat_schutzbereich", "pat_beschreibung", "pat_anmeldung"]),
    # ------------------------------------------------------------------ Wirkung und Verletzung
    c("pat_benutzungshandlungen", "Wirkung des Patents und Benutzungshandlungen (§ 9 PatG)", W,
      "Das Patent hat die Wirkung, dass allein der Inhaber befugt ist, die Erfindung zu benutzen; Dritten ist ohne Zustimmung verboten, ein Erzeugnis herzustellen, anzubieten, in Verkehr zu bringen, zu gebrauchen, einzuführen oder zu besitzen (§ 9 S. 2 Nr. 1 PatG), ein Verfahren anzuwenden oder anzubieten (Nr. 2) und das unmittelbare Verfahrenserzeugnis zu verwerten (Nr. 3).",
      "Die Handlungen sind abschließend aufgezählt und selbständig (jede verletzt für sich). Anbieten ist weit zu verstehen (auch Werbung ohne Lieferbereitschaft). Sinnfällige Herrichtung einer Vorrichtung ist keine Anwendung des Verfahrens (Abgasreinigungsvorrichtung). Inlandsbezug erforderlich.",
      norms=["§ 9 PatG"], cases=["pat_bgh_abgasreinigungsvorrichtung", "pat_bgh_rezeptortyrosinkinase_ii"], related=["pat_verletzung", "pat_verfahrenserzeugnis", "pat_erschoepfung", "pat_mittelbare_verletzung"]),
    c("pat_verfahrenserzeugnis", "Unmittelbares Verfahrenserzeugnis (§ 9 S. 2 Nr. 3 PatG)", W,
      "Der Schutz eines Verfahrenspatents erstreckt sich auf das durch das Verfahren unmittelbar hergestellte Erzeugnis; unmittelbar ist das Erzeugnis, das am Ende des Verfahrens vorliegt, nicht das nach weiterer Bearbeitung entstandene Produkt.",
      "Datenfolgen sind kein Erzeugnis (Rezeptortyrosinkinase II); bei bearbeiteten Halbzeugen ist das Halbzeug, nicht das Endprodukt geschützt (Wasserdichter Lederschuh). Beweislastumkehr für neue Erzeugnisse: § 139 Abs. 3 PatG.",
      norms=["§ 9 PatG", "§ 139 Abs. 3 PatG"], cases=["pat_bgh_rezeptortyrosinkinase_ii", "pat_bgh_wasserdichter_lederschuh"], related=["pat_benutzungshandlungen"]),
    c("pat_verletzung", "Patentverletzung (Prüfungsaufbau)", W,
      "Eine Patentverletzung liegt vor, wenn ein Dritter ohne Zustimmung des Inhabers eine Benutzungshandlung nach § 9 oder § 10 PatG im Inland vornimmt, die Ausführungsform in den Schutzbereich fällt (wortsinngemäß oder äquivalent) und keine Schranke (§§ 11, 12 PatG, Erschöpfung, Lizenz) eingreift.",
      "Aufbau der Verletzungsklage: Aktivlegitimation (Inhaber, § 30 Abs. 3; ausschließlicher Lizenznehmer), Rechtsbestand (Verletzungsgericht prüft nicht, § 148 ZPO), Merkmalsanalyse, Auslegung, Subsumtion (wortsinngemäß, dann äquivalent), Benutzungshandlung, Einwendungen, Rechtsfolgen (§§ 139 ff.). Zuständig: Patentstreitkammern (§ 143).",
      norms=["§ 9 PatG", "§ 10 PatG", "§ 14 PatG", "§ 139 PatG", "§ 143 PatG"], cases=["pat_bgh_kreuzgestaenge"], related=["pat_benutzungshandlungen", "pat_aequivalenz", "pat_mittelbare_verletzung", "pat_unterlassung", "pat_schranken"]),
    c("pat_mittelbare_verletzung", "Mittelbare Patentverletzung (§ 10 PatG)", W,
      "Verboten ist, ohne Zustimmung Mittel, die sich auf ein wesentliches Element der Erfindung beziehen, an Nichtberechtigte zur Benutzung der Erfindung im Inland anzubieten oder zu liefern, wenn der Dritte weiß oder es offensichtlich ist, dass die Mittel dazu geeignet und bestimmt sind (§ 10 Abs. 1 PatG).",
      "Doppelter Inlandsbezug (Angebot und Benutzung im Inland). Wesentliches Element: funktionales Zusammenwirken mit Anspruchsmerkmalen (Flügelradzähler). Allgemein im Handel erhältliche Erzeugnisse nur bei bewusster Veranlassung (Abs. 2). Eigenständiger Tatbestand, keine Teilnahme; Schadensersatz setzt Wahrscheinlichkeit unmittelbarer Benutzung voraus (Fräsverfahren).",
      norms=["§ 10 PatG"], cases=["pat_bgh_fluegelradzaehler", "pat_bgh_fraesverfahren", "pat_bgh_abgasreinigungsvorrichtung"], related=["pat_benutzungshandlungen", "pat_verletzung"]),
    c("pat_schranken", "Schranken der Patentwirkung (§ 11 PatG)", W,
      "Die Wirkung des Patents erstreckt sich nicht auf Handlungen im privaten Bereich zu nichtgewerblichen Zwecken, Handlungen zu Versuchszwecken, die sich auf den Gegenstand der Erfindung beziehen, Studien für arzneimittelrechtliche Zulassungen (Bolar), Einzelzubereitungen in Apotheken sowie auf Schiffe, Luft- und Landfahrzeuge im Transit (§ 11 PatG).",
      "Versuchsprivileg umfasst auch klinische Versuche zur Gewinnung von Erkenntnissen über den Erfindungsgegenstand (BGH Klinische Versuche I, II), nicht Versuche mit dem Gegenstand zu anderen Zwecken. Bolar-Ausnahme (Nr. 2b) seit 2005. Weitere Schranken: Vorbenutzungsrecht (§ 12), Erschöpfung, Zwangslizenz (§ 24), Staatsbenutzung (§ 13).",
      norms=["§ 11 PatG", "§ 12 PatG", "§ 13 PatG"], cases=[], related=["pat_vorbenutzungsrecht", "pat_erschoepfung", "pat_zwangslizenz"]),
    c("pat_vorbenutzungsrecht", "Vorbenutzungsrecht (§ 12 PatG)", W,
      "Das Patent wirkt nicht gegen den, der die Erfindung zum Zeitpunkt der Anmeldung (Prioritätstag) bereits im Inland in Benutzung genommen oder die dazu erforderlichen Veranstaltungen getroffen hatte; er darf sie für die Bedürfnisse seines Betriebs weiterbenutzen (§ 12 Abs. 1 PatG).",
      "Voraussetzungen: Erfindungsbesitz (Kenntnis der Lehre), Benutzung oder ernsthafte Veranstaltungen, Redlichkeit (nicht vom Anmelder entnommen). Übertragbar nur mit dem Betrieb (Abs. 1 S. 3). Kein Vorbenutzungsrecht aus bloßem Erfindungsbesitz ohne Benutzungswillen. Für das EPG gilt nationales Recht (Art. 28 EPGÜ).",
      norms=["§ 12 PatG"], cases=[], related=["pat_schranken", "pat_neuheit"]),
    c("pat_erschoepfung", "Erschöpfung und Reparatur", W,
      "Mit dem Inverkehrbringen eines patentgeschützten Erzeugnisses im EWR durch den Inhaber oder mit seiner Zustimmung ist das Patentrecht an diesem Exemplar erschöpft; Weiterveräußerung und bestimmungsgemäßer Gebrauch sind frei, nicht aber die Neuherstellung.",
      "Ungeschriebene Schranke (im EPGÜ Art. 29). Abgrenzung Reparatur/Neuherstellung: Verkehrsauffassung, ob der Austausch üblicher Erhalt ist, und ob sich die technischen Wirkungen der Erfindung gerade im ausgetauschten Teil widerspiegeln (Palettenbehälter II, Trommeleinheit). Keine internationale Erschöpfung: Vertrieb außerhalb des EWR in Verkehr gebrachter Ware ist Verletzung (Tintenpatrone).",
      norms=["§ 9 PatG"], cases=["pat_bgh_palettenbehaelter_ii", "pat_bgh_trommeleinheit", "pat_bgh_tintenpatrone"], related=["pat_benutzungshandlungen", "pat_schranken"]),
    c("pat_unterlassung", "Unterlassungsanspruch und Verhältnismäßigkeit (§ 139 Abs. 1 PatG)", W,
      "Wer entgegen §§ 9 bis 13 PatG eine patentierte Erfindung benutzt, kann bei Wiederholungs- oder Erstbegehungsgefahr auf Unterlassung in Anspruch genommen werden (§ 139 Abs. 1 S. 1, 2 PatG); der Anspruch ist ausgeschlossen, soweit er wegen besonderer Umstände zu einer unverhältnismäßigen Härte führen würde (§ 139 Abs. 1 S. 3 PatG), dann Ausgleich in Geld (S. 4).",
      "Verschuldensunabhängig. Verhältnismäßigkeitseinwand seit 2021 (Umsetzung von Art. 3 DurchsetzungsRL), praktisch für komplexe Produkte und Aufbrauchfristen. Vollstreckung nach § 890 ZPO. Parallel Art. 63 EPGÜ.",
      norms=["§ 139 Abs. 1 PatG"], cases=["pat_bgh_tintenpatrone"], related=["pat_verletzung", "pat_schadensersatz", "pat_rechtsfolgen_nebenanspruche"]),
    c("pat_schadensersatz", "Schadensersatz (§ 139 Abs. 2 PatG)", W,
      "Wer die Verletzung vorsätzlich oder fahrlässig begeht, ist zum Ersatz des Schadens verpflichtet (§ 139 Abs. 2 PatG); der Verletzte kann nach den drei Berechnungsarten wählen: konkreter Schaden, Herausgabe des Verletzergewinns oder angemessene Lizenzgebühr (Lizenzanalogie).",
      "Fahrlässigkeit wird bei gewerblichen Verletzern regelmäßig bejaht (Pflicht zur Schutzrechtsprüfung). Zur Bezifferung dienen Auskunft und Rechnungslegung (§ 140b PatG, § 242 BGB). Bei mittelbarer Verletzung Wahrscheinlichkeit unmittelbarer Benutzung (Fräsverfahren). Verjährung § 141 PatG; Restschadensersatz nach Bereicherungsrecht. Parallel Art. 68 EPGÜ, Art. 13 DurchsetzungsRL.",
      norms=["§ 139 Abs. 2 PatG", "§ 141 PatG", "§ 140b PatG"], cases=["pat_bgh_fraesverfahren"], related=["pat_unterlassung", "pat_rechtsfolgen_nebenanspruche"]),
    c("pat_rechtsfolgen_nebenanspruche", "Vernichtung, Rückruf, Auskunft, Urteilsbekanntmachung (§§ 140a bis 140e PatG)", W,
      "Neben Unterlassung und Schadensersatz stehen dem Verletzten Vernichtung, Rückruf und Entfernung aus den Vertriebswegen (§ 140a PatG), Auskunft über Herkunft und Vertriebsweg einschließlich Drittauskunft (§ 140b PatG), Vorlage und Besichtigung (§ 140c PatG), Sicherung von Schadensersatzansprüchen (§ 140d PatG) und Urteilsbekanntmachung (§ 140e PatG) zu.",
      "Umsetzung der Durchsetzungsrichtlinie 2004/48/EG; jede Vorschrift enthält einen Verhältnismäßigkeitsvorbehalt. Der unselbständige Rechnungslegungsanspruch aus § 242 BGB bleibt daneben. Zollbeschlagnahme: §§ 142a, 142b PatG. Entsprechungen im EPGÜ: Art. 59 bis 64, 67, 80.",
      norms=["§ 140a PatG", "§ 140b PatG", "§ 140c PatG", "§ 140d PatG", "§ 140e PatG"], cases=["pat_bgh_restschadstoffentfernung"], related=["pat_besichtigung", "pat_schadensersatz", "pat_unterlassung"]),
    c("pat_besichtigung", "Besichtigung und Vorlage (§ 140c PatG)", W,
      "Bei hinreichender Wahrscheinlichkeit einer Patentverletzung kann der Verletzte vom vermeintlichen Verletzer Vorlage einer Urkunde oder Besichtigung einer Sache verlangen, auch im Wege der einstweiligen Verfügung; Geschäftsgeheimnisse sind durch Verfahrensgestaltung zu wahren (§ 140c PatG).",
      "„Düsseldorfer Verfahren“: Besichtigung durch einen zur Verschwiegenheit verpflichteten Sachverständigen mit anschließendem Freigabeverfahren. Grundlage im allgemeinen Recht: § 809 BGB (BGH Faxkarte), § 142 ZPO (Restschadstoffentfernung). Umsetzung der Art. 6, 7 DurchsetzungsRL; im EPGÜ Art. 59, 60.",
      norms=["§ 140c PatG"], cases=["pat_bgh_restschadstoffentfernung"], related=["pat_rechtsfolgen_nebenanspruche"]),
    c("pat_trennungsprinzip", "Trennungsprinzip und Aussetzung", W,
      "Verletzung und Rechtsbestand werden in Deutschland getrennt geprüft: Über die Verletzung entscheiden die Patentstreitkammern der Landgerichte (§ 143 PatG), über die Nichtigkeit das BPatG und in der Berufung der BGH (§§ 81, 110 PatG); das Verletzungsgericht kann nach § 148 ZPO aussetzen, wenn die Vernichtung des Patents hinreichend wahrscheinlich ist.",
      "Kein Nichtigkeitseinwand im Verletzungsprozess (anders die Widerklage vor dem EPG, Art. 33 Abs. 3 EPGÜ). Aussetzungsmaßstab: überwiegende Wahrscheinlichkeit; im Berufungs- und Nichtzulassungsverfahren großzügiger (Klimaschrank, Adalimumab). Das Verletzungsgericht legt selbständig aus (Kreuzgestänge). „Injunction gap“ als Kritikpunkt.",
      norms=["§ 143 PatG", "§ 81 PatG"], cases=["pat_bgh_klimaschrank", "pat_bgh_adalimumab", "pat_bgh_kreuzgestaenge"], related=["pat_aussetzung", "pat_nichtigkeitsklage", "pat_verletzung"]),
    c("pat_aussetzung", "Aussetzung des Verletzungsprozesses (§ 148 ZPO)", W,
      "Das Verletzungsgericht kann den Rechtsstreit aussetzen, wenn ein Einspruchs- oder Nichtigkeitsverfahren anhängig ist und mit hinreichender Wahrscheinlichkeit zur Vernichtung des Klagepatents führen wird; die Aussetzung steht im Ermessen und ist wegen des Zeitverlusts für den Patentinhaber die Ausnahme.",
      "Maßstab in erster Instanz: überwiegende Wahrscheinlichkeit des Widerrufs; in der Berufung und im Nichtzulassungsbeschwerdeverfahren kann auch eine später erhobene Nichtigkeitsklage genügen, wenn besondere Umstände vorliegen (Klimaschrank, Adalimumab).",
      norms=["§ 81 PatG", "§ 139 PatG"], cases=["pat_bgh_klimaschrank", "pat_bgh_adalimumab"], related=["pat_trennungsprinzip", "pat_nichtigkeitsklage"]),
    c("pat_klagekonzentration", "Klagekonzentration (§ 145 PatG)", W,
      "Wer wegen Verletzung eines Patents Klage erhoben hat, kann gegen den Beklagten wegen derselben oder einer gleichartigen Handlung aus einem anderen Patent nur klagen, wenn er ohne Verschulden nicht in der Lage war, auch dieses Patent im ersten Rechtsstreit geltend zu machen (§ 145 PatG).",
      "Schutz des Beklagten vor gestaffelten Klagen. Gleichartig sind nur Handlungen mit zusätzlichen oder abgewandelten Merkmalen (Raffvorhang); die Vorschrift ist eng auszulegen und gilt nicht für Gebrauchsmuster.",
      norms=["§ 145 PatG"], cases=["pat_bgh_raffvorhang"], related=["pat_verletzung"]),
    c("pat_lizenz", "Lizenz und Übertragung (§ 15 PatG)", W,
      "Das Recht auf das Patent, der Anspruch auf Erteilung und das Patent sind übertragbar und können ganz oder teilweise Gegenstand ausschließlicher oder einfacher Lizenzen sein (§ 15 Abs. 1, 2 PatG); ein Rechtsübergang lässt zuvor erteilte Lizenzen unberührt (§ 15 Abs. 3 PatG, Sukzessionsschutz).",
      "Der ausschließliche Lizenznehmer ist aus eigenem Recht klagebefugt; der einfache nur mit Ermächtigung (gewillkürte Prozessstandschaft). Registereintragung ist nicht Wirksamkeitsvoraussetzung, aber § 30 Abs. 3 PatG (Legitimation). Lizenzbereitschaft: § 23 PatG. Zwangslizenz: § 24 PatG.",
      norms=["§ 15 PatG", "§ 30 Abs. 3 PatG", "§ 23 PatG"], cases=[], related=["pat_zwangslizenz", "pat_register", "pat_verletzung"]),
    # ------------------------------------------------------------------ Anmeldung und Erteilung
    c("pat_anmeldung", "Patentanmeldung (§ 34 PatG, PatV)", A,
      "Die Anmeldung ist beim DPMA einzureichen und muss Erteilungsantrag, Patentansprüche, Beschreibung, Zeichnungen und Zusammenfassung enthalten (§ 34 Abs. 3 PatG); Form und Inhalt regelt die PatV (§ 34 Abs. 6 PatG). Sie darf nur eine Erfindung oder eine Gruppe einheitlicher Erfindungen betreffen (§ 34 Abs. 5 PatG).",
      "Anmeldetag nach § 35 PatG mit Mindesterfordernissen; Zeichnungen sind kein Mindesterfordernis (BPatG Mobilfunknetzwerk). Formvorschriften der PatV dienen der Verständlichkeit (BPatG Aufreißdeckel). Anmeldegebühr 40 EUR elektronisch (Nr. 311 000), zahlbar binnen drei Monaten (§ 6 Abs. 1 PatKostG), sonst Rücknahmefiktion.",
      norms=["§ 34 PatG", "§ 35 PatG", "§ 5 PatV", "§ 6 PatV", "§ 6 Abs. 1 PatKostG"], cases=["pat_bpatg_mobilfunknetzwerk", "pat_bpatg_aufreissdeckel"], related=["pat_anmeldetag", "pat_patentanspruch", "pat_beschreibung", "pat_pruefungsverfahren", "pat_gebuehren"]),
    c("pat_anmeldetag", "Anmeldetag (§ 35 PatG)", A,
      "Anmeldetag ist der Tag, an dem beim DPMA der Erteilungsantrag, Angaben zur Identifizierung des Anmelders und eine (auch fremdsprachige) Beschreibung eingegangen sind (§ 35 Abs. 1 PatG); eine Übersetzung ist binnen drei Monaten nachzureichen, sonst gilt die Anmeldung als zurückgenommen (§ 35 Abs. 2 PatG).",
      "Der Anmeldetag ist Zeitrang für Neuheit und Priorität (§ 3 Abs. 1, § 40 PatG) und Beginn der Laufzeit (§ 16 PatG) und der Jahresgebührenrechnung (§ 3 Abs. 2 PatKostG). Fehlende Teile: § 35a PatG; englische oder französische Anmeldungen: zwölf Monate Übersetzungsfrist.",
      norms=["§ 35 PatG", "§ 35a PatG", "§ 16 PatG"], cases=["pat_bpatg_mobilfunknetzwerk"], related=["pat_anmeldung", "pat_prioritaet"]),
    c("pat_beschreibung", "Beschreibung (§ 10 PatV)", A,
      "Die Beschreibung nennt das technische Gebiet, den Stand der Technik, die Aufgabe, die Lösung, die erzielten Vorteile und mindestens ein Ausführungsbeispiel (§ 10 Abs. 2 PatV); sie muss die Erfindung so offenbaren, dass ein Fachmann sie ausführen kann (§ 34 Abs. 4 PatG).",
      "Die Beschreibung ist Auslegungsmittel (§ 14 PatG) und Maßstab der Offenbarung (§ 38 PatG); Herabsetzungen Dritter und irrelevante Angaben können gestrichen werden (§ 10 Abs. 4 PatV). Zusammenfassung (§ 13 PatV, § 36 PatG) dient nur der Information.",
      norms=["§ 10 PatV", "§ 13 PatV", "§ 34 Abs. 4 PatG", "§ 36 PatG"], cases=["pat_bpatg_aufreissdeckel"], related=["pat_anmeldung", "pat_ausfuehrbarkeit", "pat_aufgabe_loesung"]),
    c("pat_recht_auf_patent", "Recht auf das Patent, Erfinderprinzip, widerrechtliche Entnahme (§§ 6 bis 8 PatG)", A,
      "Das Recht auf das Patent hat der Erfinder oder sein Rechtsnachfolger (§ 6 PatG); im Verfahren vor dem DPMA gilt der Anmelder als berechtigt (§ 7 Abs. 1 PatG). Wer durch widerrechtliche Entnahme betroffen ist, kann Abtretung der Anmeldung oder Übertragung des Patents verlangen (§ 8 PatG, Vindikation) oder Einspruch einlegen (§ 21 Abs. 1 Nr. 3 PatG).",
      "Bei Doppelerfindung gilt das Prioritätsprinzip (§ 6 S. 3). Arbeitnehmererfindungen: Inanspruchnahme nach § 6 ArbnErfG. Fristen der Vindikation: zwei Jahre nach Erteilungsveröffentlichung, außer bei Bösgläubigkeit (§ 8 S. 3, 4). Nachanmeldung mit Priorität der entnommenen Anmeldung nach erfolgreichem Einspruch (§ 7 Abs. 2 PatG). Für europäische Anmeldungen Art. II § 5 IntPatÜG.",
      norms=["§ 6 PatG", "§ 7 PatG", "§ 8 PatG", "Art. II § 5 IntPatÜG"], cases=[], related=["pat_widerrufsgruende", "pat_anmeldung"]),
    c("pat_prioritaet", "Priorität (§§ 40, 41 PatG)", A,
      "Innerhalb von zwölf Monaten nach einer ersten Anmeldung kann für dieselbe Erfindung deren Zeitrang beansprucht werden: innere Priorität einer deutschen Voranmeldung (§ 40 PatG) oder Unionspriorität einer ausländischen Anmeldung nach der PVÜ (§ 41 PatG); die Prioritätserklärung ist binnen 16 Monaten abzugeben.",
      "Maßstab: Die Erfindung muss in der Voranmeldung als zur Erfindung gehörend offenbart sein, derselbe Offenbarungsbegriff wie bei § 38 (Kommunikationskanal). Das Prioritätsrecht ist formlos übertragbar, aber vor der Nachanmeldung (Fahrzeugscheibe). Keine Wiedereinsetzung in die Prioritätsfrist (§ 123 Abs. 1 S. 2; BPatG Mehrfach-Funkgerät). Die deutsche Voranmeldung gilt bei innerer Priorität als zurückgenommen (§ 40 Abs. 5).",
      norms=["§ 40 PatG", "§ 41 PatG", "§ 123 Abs. 1 PatG"], cases=["pat_bgh_fahrzeugscheibe", "pat_bgh_kommunikationskanal", "pat_bpatg_mehrfach_funkgeraet"], related=["pat_offenbarung", "pat_anmeldetag", "pat_neuheit"]),
    c("pat_teilung", "Teilung und Ausscheidung (§§ 34 Abs. 5, 39, 60 PatG)", A,
      "Der Anmelder kann die Anmeldung jederzeit bis zur Erteilung teilen; die Teilanmeldung behält Anmeldetag und Priorität, die Teilung ist unwiderruflich (§ 39 PatG). Bei Uneinheitlichkeit verlangt das DPMA eine Ausscheidung (§ 34 Abs. 5 PatG); im Einspruchsverfahren kann das Patent geteilt werden (§ 60 PatG).",
      "Die Teilungserklärung muss keinen gegenständlich bestimmten Teil benennen (Sammelhefter); für die Teilanmeldung sind Anmelde- und Jahresgebühren nachzuzahlen (§ 39 Abs. 2 PatG), bei Ausscheidung auch die Prüfungsgebühr (BPatG Prüfungsgebühr für Ausscheidungsanmeldung). Die Teilanmeldung darf nicht über die Stammanmeldung hinausgehen.",
      norms=["§ 39 PatG", "§ 34 Abs. 5 PatG", "§ 60 PatG"], cases=["pat_bgh_sammelhefter", "pat_bpatg_pruefungsgebuehr_ausscheidung"], related=["pat_anmeldung", "pat_unzulaessige_erweiterung", "pat_gebuehren"]),
    c("pat_unzulaessige_erweiterung", "Unzulässige Erweiterung (§ 38, § 21 Abs. 1 Nr. 4 PatG)", A,
      "Änderungen der Anmeldung dürfen ihren Gegenstand nicht über den Inhalt der ursprünglich eingereichten Fassung hinaus erweitern (§ 38 S. 1 PatG); ein Verstoß ist Widerrufs- und Nichtigkeitsgrund (§ 21 Abs. 1 Nr. 4, § 22 Abs. 1 PatG, Art. II § 6 Abs. 1 Nr. 3 IntPatÜG). Maßstab ist, was der Fachmann den ursprünglichen Unterlagen unmittelbar und eindeutig als zur Erfindung gehörend entnimmt.",
      "Vor der Prüfung ist der geänderte Anspruch auszulegen (Rotorelemente). Verallgemeinerungen von Ausführungsbeispielen sind zulässig, wenn sie erkennbar zur Erfindung gehören (Einkaufswagen II); Aliud führt zum Widerruf, ein bloß beschränkendes, nicht offenbartes Merkmal bleibt im Anspruch, wird aber bei der Patentfähigkeit nicht berücksichtigt (Winkelmesseinrichtung, Wundbehandlungsvorrichtung). Weglassen ist nicht Ersetzen (Überbrücktes Netzwerk). Abgrenzung: Erweiterung des Schutzbereichs nach Erteilung (§ 22 Abs. 1 Alt. 2).",
      norms=["§ 38 PatG", "§ 21 Abs. 1 Nr. 4 PatG", "§ 22 Abs. 1 PatG", "Art. II § 6 Abs. 1 Nr. 3 IntPatÜG"], cases=["pat_bgh_hubgliedertor_i", "pat_bgh_winkelmesseinrichtung", "pat_bgh_rotorelemente", "pat_bgh_wundbehandlungsvorrichtung", "pat_bgh_einkaufswagen_ii", "pat_bgh_ueberbruecktes_netzwerk", "pat_bgh_phosphatidylcholin"], related=["pat_offenbarung", "pat_widerrufsgruende", "pat_nichtigkeitsgruende"]),
    c("pat_pruefungsverfahren", "Prüfungsverfahren: Recherche, Prüfungsantrag, Erteilung (§§ 42 bis 49 PatG)", A,
      "Nach der Offensichtlichkeitsprüfung (§ 42 PatG) wird die Anmeldung nur auf Prüfungsantrag sachlich geprüft; der Antrag ist binnen sieben Jahren ab Anmeldetag von jedermann stellbar (§ 44 PatG), sonst gilt die Anmeldung als zurückgenommen. Genügt die Anmeldung den Anforderungen, ergeht der Erteilungsbeschluss (§ 49 PatG), sonst Zurückweisung (§ 48 PatG).",
      "Rechercheantrag (§ 43) ohne Prüfung, Gebühr 300 EUR, anrechenbar. Prüfungsgebühr 350 EUR (150 EUR nach Recherche), zahlbar binnen drei Monaten (§ 6 PatKostG). Rechtliches Gehör: Zurückweisung nur aus mitgeteilten Gründen (§ 48 i.V.m. § 42 Abs. 3). Über Haupt- und Hilfsanträge ist einheitlich zu entscheiden (BPatG Teilbeschluss). Offenlegung 18 Monate nach Anmeldung (§ 32 Abs. 5), Entschädigung § 33.",
      norms=["§ 42 PatG", "§ 43 PatG", "§ 44 PatG", "§ 45 PatG", "§ 48 PatG", "§ 49 PatG", "§ 6 Abs. 1 PatKostG"], cases=["pat_bpatg_teilbeschluss", "pat_bgh_phosphatidylcholin"], related=["pat_anmeldung", "pat_gebuehren", "pat_beschwerde", "pat_weiterbehandlung"]),
    c("pat_register", "Patentregister und Registerfiktion (§ 30 PatG)", A,
      "Das DPMA führt das Register mit Anmeldungen, Patenten, Inhabern, Vertretern, Lizenzen und Erlöschen; wer als Inhaber eingetragen ist, gilt im Verfahren vor dem DPMA und dem Patentgericht als berechtigt (§ 30 Abs. 3 S. 2 PatG).",
      "Die Umschreibung erfolgt nur auf Antrag mit Nachweis des Rechtsübergangs. Die Registerfiktion betrifft die formelle Legitimation; im Verletzungsprozess ist der materiell Berechtigte aktivlegitimiert, die Eintragung begründet aber eine Vermutung. Lizenzbereitschaft (§ 23) und ausschließliche Lizenzen werden vermerkt.",
      norms=["§ 30 PatG", "§ 23 PatG"], cases=[], related=["pat_lizenz", "pat_akteneinsicht"]),
    c("pat_akteneinsicht", "Akteneinsicht und Offenlegung (§§ 31, 32 PatG)", A,
      "Einsicht in die Akten der Anmeldung steht jedermann frei, sobald die Anmeldung offengelegt ist oder der Anmelder zugestimmt hat (§ 31 PatG); die Offenlegungsschrift wird 18 Monate nach dem Anmelde- oder Prioritätstag veröffentlicht (§ 32 Abs. 5 PatG).",
      "Vor der Offenlegung nur mit Zustimmung oder bei berechtigtem Interesse; geheime Patente (§§ 50 ff.) bleiben ausgenommen. Mit der Offenlegung entsteht der Entschädigungsanspruch (§ 33 PatG) und die Anmeldung wird Stand der Technik (§ 3 Abs. 1).",
      norms=["§ 31 PatG", "§ 32 PatG", "§ 33 PatG"], cases=[], related=["pat_register", "pat_anmeldung"]),
    c("pat_erfinderbenennung", "Erfinderbenennung und Erfindernennung (§§ 37, 63 PatG; § 7 PatV)", A,
      "Der Anmelder hat binnen 15 Monaten ab Anmeldetag oder Prioritätstag den Erfinder zu benennen und zu versichern, dass keine weiteren Personen beteiligt sind (§ 37 Abs. 1 PatG); der Erfinder hat das Recht, in Patentschrift und Register genannt zu werden (§ 63 PatG).",
      "Die Benennung erfolgt in gesonderter Erklärung nach § 7 PatV; Nachfrist gegen Gebühr, sonst keine Erteilung. Erfinderpersönlichkeitsrecht: Verzicht auf die Nennung ist möglich (§ 63 Abs. 1 S. 3, § 8 PatV), ein Vorausverzicht auf das Recht selbst nicht.",
      norms=["§ 37 PatG", "§ 63 PatG", "§ 7 PatV", "§ 8 PatV"], cases=[], related=["pat_anmeldung", "pat_recht_auf_patent"]),
    c("pat_laufzeit_jahresgebuehren", "Laufzeit und Jahresgebühren (§§ 16, 17, 20 PatG)", A,
      "Das Patent dauert 20 Jahre ab dem Tag nach der Anmeldung (§ 16 PatG); ab dem dritten Jahr sind Jahresgebühren zu zahlen (§ 17 PatG), bei deren Nichtzahlung das Patent erlischt (§ 20 Abs. 1 Nr. 3 PatG).",
      "Fälligkeit und Fristen: § 3 Abs. 2, § 7 PatKostG (zwei Monate zuschlagsfrei, sechs Monate mit 50 EUR Zuschlag). Halbierung bei Lizenzbereitschaft (§ 23 Abs. 1). Für europäische Patente an das DPMA nach Art. II § 7 IntPatÜG, für Einheitspatente an das EPA. Verlängerung nur über ESZ (§ 16a). Wiedereinsetzung nach Erlöschen: § 123 mit Zwischenbenutzungsrecht.",
      norms=["§ 16 PatG", "§ 17 PatG", "§ 20 PatG", "§ 23 PatG", "§ 7 PatKostG", "Art. II § 7 IntPatÜG"], cases=["pat_bgh_verdickerpolymer_ii", "pat_bpatg_saegeblatt"], related=["pat_jahresgebuehren", "pat_wiedereinsetzung", "pat_schutzzertifikat"]),
    c("pat_schutzzertifikat", "Ergänzendes Schutzzertifikat (§§ 16a, 49a PatG)", A,
      "Für Arzneimittel und Pflanzenschutzmittel, deren Vermarktung eine behördliche Genehmigung voraussetzt, kann nach den Verordnungen (EG) Nr. 469/2009 und Nr. 1610/96 ein ergänzendes Schutzzertifikat erteilt werden, das den Schutz des Grundpatents für das genehmigte Erzeugnis um bis zu fünf Jahre verlängert (§ 16a PatG); Verfahren und Antrag: § 49a PatG, §§ 20, 21 PatV.",
      "Voraussetzungen (Art. 3 VO 469/2009): Grundpatent in Kraft, gültige erste Genehmigung, Erzeugnis durch das Grundpatent geschützt, kein früheres Zertifikat. Laufzeit: Zeit zwischen Anmeldung des Grundpatents und erster Genehmigung minus fünf Jahre, höchstens fünf Jahre; pädiatrische Verlängerung sechs Monate. Nichtigkeit im Verfahren nach § 81 PatG (Art. II § 6a IntPatÜG für EP-Grundpatente). Gebühren Nr. 311 500 ff., 312 210 ff.",
      norms=["§ 16a PatG", "§ 49a PatG", "§ 20 PatV", "Art. II § 6a IntPatÜG"], cases=["pat_bgh_escitalopram"], related=["pat_laufzeit_jahresgebuehren"]),
    # ------------------------------------------------------------------ Einspruch, Beschränkung
    c("pat_einspruch", "Einspruch (§ 59 PatG)", E,
      "Innerhalb von neun Monaten nach Veröffentlichung der Erteilung kann jeder Einspruch einlegen; er ist schriftlich zu erklären, zu begründen und kann nur auf die Widerrufsgründe des § 21 PatG gestützt werden (§ 59 Abs. 1 PatG). Über den Einspruch entscheidet die Patentabteilung (§ 61 PatG); dagegen Beschwerde zum Technischen Beschwerdesenat (§ 73 PatG).",
      "Gebühr 200 EUR (Nr. 313 600), für jeden Einsprechenden gesondert (BPatG Einspruchsgebühren bei gemeinsamem Einspruch), zahlbar binnen der Einspruchsfrist (§ 6 Abs. 1 S. 2 PatKostG). Begründung muss die Tatsachen so vollständig angeben, dass abschließende Folgerungen möglich sind (Leistungshalbleiterbauelement). Beitritt des Verletzungsbeklagten, auch bei einstweiliger Verfügung (§ 59 Abs. 2; Ratschenschlüssel). Während des Einspruchs keine Nichtigkeitsklage (§ 81 Abs. 2). Keine Wiedereinsetzung in die Einspruchsfrist.",
      norms=["§ 59 PatG", "§ 61 PatG", "§ 21 PatG", "§ 6 Abs. 1 PatKostG"], cases=["pat_bgh_ratschenschluessel", "pat_bgh_leistungshalbleiterbauelement", "pat_bgh_ventileinrichtung", "pat_bpatg_einspruchsgebuehren_gemeinsam"], related=["pat_widerrufsgruende", "pat_beitritt", "pat_beschwerde", "pat_nichtigkeitsklage", "pat_beschraenkungsverfahren"]),
    c("pat_widerrufsgruende", "Widerrufsgründe (§ 21 PatG)", E,
      "Das Patent wird widerrufen, wenn der Gegenstand nicht patentfähig ist (Nr. 1), die Erfindung nicht ausführbar offenbart ist (Nr. 2), der wesentliche Inhalt widerrechtlich entnommen wurde (Nr. 3) oder der Gegenstand über den Inhalt der ursprünglichen Anmeldung hinausgeht (Nr. 4); betreffen die Gründe nur einen Teil, wird das Patent beschränkt aufrechterhalten (§ 21 Abs. 2 PatG).",
      "Abschließender Katalog; mangelnde Klarheit und Uneinheitlichkeit sind keine Widerrufsgründe. Nr. 3 kann nur der Verletzte geltend machen. Im Beschwerdeverfahren keine neuen Widerrufsgründe von Amts wegen (Ventileinrichtung). Die Nichtigkeitsgründe des § 22 PatG entsprechen dem Katalog plus Schutzbereichserweiterung; für europäische Patente Art. 138 EPÜ über Art. II § 6 IntPatÜG.",
      norms=["§ 21 PatG", "§ 22 PatG", "Art. II § 6 IntPatÜG"], cases=["pat_bgh_winkelmesseinrichtung", "pat_bgh_ventileinrichtung"], related=["pat_einspruch", "pat_nichtigkeitsgruende", "pat_unzulaessige_erweiterung", "pat_ausfuehrbarkeit"]),
    c("pat_beitritt", "Beitritt zum Einspruchsverfahren (§ 59 Abs. 2 PatG)", E,
      "Wer nachweist, dass gegen ihn Verletzungsklage aus dem Patent erhoben oder er vom Inhaber zur Unterlassung aufgefordert wurde, kann dem Einspruchsverfahren binnen drei Monaten beitreten (§ 59 Abs. 2 PatG); der Beitritt hat die Stellung eines Einspruchs.",
      "Auch das Verfügungsverfahren ist Verletzungsklage in diesem Sinne (Ratschenschlüssel). Der Beitritt eröffnet den Angriff auf den Rechtsbestand nach Ablauf der Einspruchsfrist, solange das Einspruchsverfahren anhängig ist; danach nur Nichtigkeitsklage (§ 81 Abs. 2).",
      norms=["§ 59 Abs. 2 PatG"], cases=["pat_bgh_ratschenschluessel"], related=["pat_einspruch"]),
    c("pat_beschraenkungsverfahren", "Beschränkung und Widerruf auf Antrag (§ 64 PatG)", E,
      "Der Patentinhaber kann jederzeit beim DPMA beantragen, das Patent durch Änderung der Ansprüche zu beschränken oder zu widerrufen (§ 64 PatG); die Beschränkung wirkt auf den Anmeldetag zurück.",
      "Werkzeug zur Sicherung des Rechtsbestands vor einer Nichtigkeitsklage; keine Erweiterung (§ 38, § 22 Abs. 1). Abzugrenzen von der beschränkten Verteidigung im Einspruch (§ 21 Abs. 2) und im Nichtigkeitsverfahren (§ 22 Abs. 2, Art. II § 6 Abs. 3 IntPatÜG). Gebühr Nr. 313 700.",
      norms=["§ 64 PatG", "§ 21 Abs. 2 PatG"], cases=[], related=["pat_beschraenkte_verteidigung", "pat_einspruch"]),
    # ------------------------------------------------------------------ Nichtigkeit, Zwangslizenz
    c("pat_nichtigkeitsklage", "Nichtigkeitsklage (§§ 81 ff. PatG)", N,
      "Das Patent wird auf Klage für nichtig erklärt, wenn ein Nichtigkeitsgrund des § 22 PatG vorliegt; die Klage ist beim Patentgericht zu erheben, jedermann ist klagebefugt (Popularklage), während eines Einspruchsverfahrens ist sie unzulässig (§ 81 Abs. 2 PatG). Die Nichtigkeitssenate entscheiden durch Urteil (§ 84 PatG), Berufung zum BGH (§ 110 PatG).",
      "Verfahren: Klage und Zustellung (§ 82), Widerspruch binnen eines Monats, qualifizierter Hinweis mit Fristsetzung und Präklusion (§ 83), mündliche Verhandlung, Urteil mit Kostenentscheidung nach §§ 91 ff. ZPO (§ 84 Abs. 2). Gebühr 4,5 Wertgebühren (Nr. 402 100), Streitwert § 121. Kein Rechtsmissbrauch bei paralleler Klage (Benutzerauthentifizierung); Nebenintervention weit (Carvedilol, Pemetrexed II). Für europäische Patente: Art. II § 6 IntPatÜG, Klagesperre auch bei EPA-Einspruch (BPatG Torasemid). Neben dem EPG (Art. 32, 83 EPGÜ) nur bei Opt-out oder in der Übergangszeit.",
      norms=["§ 81 PatG", "§ 82 PatG", "§ 83 PatG", "§ 84 PatG", "§ 22 PatG", "§ 121 PatG", "Art. II § 6 IntPatÜG"], cases=["pat_bgh_sensoranordnung", "pat_bgh_polymerschaum", "pat_bgh_walzstrasse", "pat_bgh_benutzerauthentifizierung", "pat_bgh_pemetrexed_ii", "pat_bgh_carvedilol_nebenintervention", "pat_bpatg_torasemid"], related=["pat_nichtigkeitsgruende", "pat_qualifizierter_hinweis", "pat_beschraenkte_verteidigung", "pat_nichtigkeitsberufung", "pat_trennungsprinzip", "pat_streitwert", "pat_nichtigkeit_ep"]),
    c("pat_nichtigkeitsgruende", "Nichtigkeitsgründe (§ 22 PatG, Art. II § 6 IntPatÜG)", N,
      "Nichtigkeitsgründe sind die Widerrufsgründe des § 21 Abs. 1 PatG und die Erweiterung des Schutzbereichs nach Erteilung (§ 22 Abs. 1 PatG); für den deutschen Teil eines europäischen Patents gelten die Gründe des Art. 138 Abs. 1 EPÜ (Art. II § 6 Abs. 1 IntPatÜG): fehlende Patentfähigkeit, mangelnde Ausführbarkeit, unzulässige Erweiterung, Schutzbereichserweiterung, fehlende Berechtigung.",
      "Abschließend: Klarheit ist kein Nichtigkeitsgrund und bei beschränkter Verteidigung nur eingeschränkt zu prüfen (Fugenband, BPatG Kaffeemaschine). Teilnichtigkeit bei nebengeordneten Ansprüchen: Entscheidung anspruchsweise (Sensoranordnung). Wirkung der Nichtigerklärung ex tunc und gegen jedermann (§ 21 Abs. 3).",
      norms=["§ 22 PatG", "§ 21 PatG", "Art. II § 6 Abs. 1 IntPatÜG"], cases=["pat_bgh_fugenband", "pat_bgh_sensoranordnung", "pat_bgh_wundbehandlungsvorrichtung"], related=["pat_widerrufsgruende", "pat_nichtigkeitsklage", "pat_unzulaessige_erweiterung", "pat_ausfuehrbarkeit"]),
    c("pat_nichtigkeit_ep", "Nichtigkeit des europäischen Patents (Art. II § 6 IntPatÜG)", N,
      "Der mit Wirkung für Deutschland erteilte deutsche Teil eines europäischen Patents wird auf Klage nach §§ 81 ff. PatG für nichtig erklärt, wenn ein Grund des Art. 138 Abs. 1 EPÜ vorliegt (Art. II § 6 Abs. 1 IntPatÜG); der Inhaber kann das Patent beschränkt verteidigen (Abs. 3).",
      "Zuständig sind die deutschen Gerichte nur, solange das EPG nicht ausschließlich zuständig ist: Opt-out oder Übergangszeit nach Art. 83 EPGÜ; für Einheitspatente ist Art. II § 6 nicht anwendbar (Art. II § 15 IntPatÜG). Klagesperre während eines EPA-Einspruchs (§ 81 Abs. 2; Torasemid). Materiell dieselben Maßstäbe wie beim deutschen Patent (Wundbehandlungsvorrichtung, Thermoplastische Zusammensetzung).",
      norms=["Art. II § 6 IntPatÜG", "§ 81 PatG", "Art. II § 15 IntPatÜG"], cases=["pat_bpatg_torasemid", "pat_bgh_wundbehandlungsvorrichtung", "pat_bgh_thermoplastische_zusammensetzung", "pat_bpatg_imidazolinpyrimidon"], related=["pat_nichtigkeitsklage", "pat_nichtigkeitsgruende", "pat_doppelschutz", "pat_ep_validierung"]),
    c("pat_qualifizierter_hinweis", "Qualifizierter Hinweis und Präklusion (§ 83 PatG)", N,
      "Das Patentgericht weist die Parteien so früh wie möglich auf die Gesichtspunkte hin, die für die Entscheidung voraussichtlich von besonderer Bedeutung sind (§ 83 Abs. 1 PatG), und setzt Fristen für Stellungnahmen (Abs. 2); verspätetes Vorbringen kann zurückgewiesen werden (Abs. 4) und bleibt in der Berufung ausgeschlossen (§ 117 PatG).",
      "Eingeführt 2009 zur Beschleunigung. Der Hinweis bindet nicht, verpflichtet aber die Parteien, auf erkennbare Bedenken zu reagieren (Walzstraße); weicht das Gericht in der Verhandlung vom Hinweis ab, ist eine geänderte Verteidigung in der Berufung sachdienlich (Fahrzeugscheibe II).",
      norms=["§ 83 PatG", "§ 117 PatG"], cases=["pat_bgh_walzstrasse", "pat_bgh_fahrzeugscheibe_ii"], related=["pat_nichtigkeitsklage", "pat_nichtigkeitsberufung"]),
    c("pat_beschraenkte_verteidigung", "Beschränkte Verteidigung und Hilfsanträge", N,
      "Der Patentinhaber kann das Patent im Einspruchs- und Nichtigkeitsverfahren durch Änderung der Ansprüche in beschränktem Umfang verteidigen (§ 21 Abs. 2, § 22 Abs. 2 PatG, Art. II § 6 Abs. 3 IntPatÜG); die beschränkte Fassung ist dem Verfahren zugrunde zu legen. Hilfsanträge werden in der gestellten Reihenfolge geprüft.",
      "Grenzen: keine unzulässige Erweiterung (§ 38), keine Schutzbereichserweiterung (§ 22 Abs. 1), Aufnahme von Merkmalen aus der Beschreibung zulässig. Klarheit wird nur geprüft, soweit die Änderung sie betrifft (Fugenband, Kaffeemaschine). Verspätete Hilfsanträge unterliegen § 83 Abs. 4, § 116 Abs. 2 (Fahrzeugscheibe II). Kostenfolge bei erst im Verfahren erklärter Beschränkung: § 84 Abs. 2 S. 2.",
      norms=["§ 22 Abs. 2 PatG", "§ 21 Abs. 2 PatG", "Art. II § 6 Abs. 3 IntPatÜG", "§ 116 Abs. 2 PatG"], cases=["pat_bgh_fugenband", "pat_bpatg_kaffeemaschine", "pat_bgh_fahrzeugscheibe_ii", "pat_bgh_sensoranordnung"], related=["pat_nichtigkeitsklage", "pat_einspruch", "pat_beschraenkungsverfahren"]),
    c("pat_nichtigkeitsberufung", "Berufung im Nichtigkeitsverfahren (§§ 110 ff. PatG)", N,
      "Gegen die Urteile der Nichtigkeitssenate findet die Berufung zum BGH statt; sie ist binnen eines Monats einzulegen und binnen drei Monaten zu begründen (§ 110 PatG). Der BGH prüft im Rahmen der Anträge und Berufungsgründe (§ 116 PatG); neue Angriffs- und Verteidigungsmittel sind nur nach § 117 PatG zulässig.",
      "Seit 2009 keine volle zweite Tatsacheninstanz mehr. Sachdienliche geänderte Verteidigung (§ 116 Abs. 2): Fahrzeugscheibe II. Präklusion bei Nachlässigkeit: Walzstraße. Nebenintervention auch in der Berufung (Pemetrexed II). Streitwert der Berufung: gemeiner Wert im angegriffenen Umfang. Der X. Zivilsenat ist Berufungs- und Rechtsbeschwerdegericht in Patentsachen.",
      norms=["§ 110 PatG", "§ 116 PatG", "§ 117 PatG", "§ 121 PatG"], cases=["pat_bgh_walzstrasse", "pat_bgh_fahrzeugscheibe_ii", "pat_bgh_pemetrexed_ii", "pat_bgh_streitwert_nichtigkeitsberufung"], related=["pat_nichtigkeitsklage", "pat_qualifizierter_hinweis", "pat_rechtsbeschwerde"]),
    c("pat_nebenintervention", "Nebenintervention im Nichtigkeitsverfahren (§ 66 ZPO)", N,
      "Über § 99 Abs. 1 PatG gilt § 66 ZPO: Wer ein rechtliches Interesse am Obsiegen einer Partei hat, kann dem Nichtigkeitsverfahren beitreten; das Interesse ist weit zu verstehen und liegt schon vor, wenn der Beitretende ein durch das Patent behindertes Unternehmen betreibt.",
      "Beitritt auch in der Berufungsinstanz und ohne eigene Klageerhebung (Carvedilol, Pemetrexed II). Der Nebenintervenient kann eigene Angriffsmittel vorbringen, ist aber an die Prozesslage gebunden (§ 67 ZPO).",
      norms=["§ 99 Abs. 1 PatG", "§ 81 PatG"], cases=["pat_bgh_carvedilol_nebenintervention", "pat_bgh_pemetrexed_ii"], related=["pat_nichtigkeitsklage"]),
    c("pat_zwangslizenz", "Zwangslizenz (§ 24 PatG)", N,
      "Das Patentgericht erteilt eine nicht ausschließliche Zwangslizenz, wenn sich der Lizenzsucher innerhalb angemessener Zeit erfolglos bemüht hat, eine Lizenz zu angemessenen Bedingungen zu erhalten, und das öffentliche Interesse die Erteilung gebietet (§ 24 Abs. 1 PatG); weitere Fälle: abhängige Erfindung mit wichtigem technischen Fortschritt (Abs. 2), Nichtausübung (Abs. 5).",
      "Klage nach § 81 PatG, einstweilige Verfügung nach § 85 PatG (Gebühr 1,5 Wertgebühren). Bemühen und öffentliches Interesse im Einzelfall: Raltegravir (Isentress, Verfügung bejaht), Alirocumab (Bemühen zu spät, verneint). Für Einheitspatente Art. II § 16 IntPatÜG. Kartellrechtlicher Zwangslizenzeinwand (FRAND) ist davon zu trennen.",
      norms=["§ 24 PatG", "§ 81 PatG", "§ 85 PatG", "Art. II § 16 IntPatÜG"], cases=["pat_bgh_raltegravir", "pat_bgh_alirocumab"], related=["pat_lizenz", "pat_schranken", "pat_nichtigkeitsklage"]),
    c("pat_streitwert", "Streitwert und Kostenentscheidung im Nichtigkeitsverfahren (§§ 84, 121 PatG)", N,
      "Der Streitwert bemisst sich nach dem gemeinen Wert des Patents bei Klageerhebung zuzüglich des bis dahin entstandenen Schadensersatzes (§ 121 Abs. 1 PatG i.V.m. § 51 GKG); die Kosten trägt die unterliegende Partei nach §§ 91 ff. ZPO, bei erst im Verfahren erklärter Beschränkung nach Billigkeit (§ 84 Abs. 2 PatG).",
      "Faustregel: Verletzungsstreitwert plus 25 %. Gebühr 4,5 Wertgebühren (Nr. 402 100), 2 EUR-Begrenzungen fehlen; Streitwertbegünstigung nach § 144 gilt entsprechend (§ 121 Abs. 2). Streitwert der Berufung im angegriffenen Umfang (BGH Streitwert im Nichtigkeitsberufungsverfahren). Patentanwaltskosten erstattungsfähig (§ 143 Abs. 3 entsprechend); Syndikusanwälte nicht (BPatG Syndikusanwalt).",
      norms=["§ 121 PatG", "§ 84 Abs. 2 PatG", "§ 144 PatG", "§ 2 Abs. 2 PatKostG"], cases=["pat_bgh_streitwert_nichtigkeitsberufung", "pat_bgh_benutzerauthentifizierung", "pat_bpatg_syndikusanwalt_kosten"], related=["pat_nichtigkeitsklage", "pat_kostenerstattung", "pat_gebuehren"]),
    c("pat_kostenerstattung", "Kostenerstattung und Patentanwaltskosten", N,
      "Im Nichtigkeitsverfahren werden die Kosten nach §§ 91 ff. ZPO erstattet (§ 84 Abs. 2 PatG); in Patentstreitsachen sind die Kosten eines mitwirkenden Patentanwalts bis zur Höhe einer Rechtsanwaltsgebühr erstattungsfähig (§ 143 Abs. 3 PatG). Im Einspruchs- und Beschwerdeverfahren trägt jeder seine Kosten selbst, Auferlegung nur aus Billigkeit (§ 62, § 80 PatG).",
      "Syndikusanwälte können ihre Tätigkeit nicht als erstattungsfähige Kosten abrechnen (BPatG Syndikusanwalt im Nichtigkeitsverfahren). Rückzahlung der Beschwerdegebühr bei Verfahrensfehlern (§ 80 Abs. 3 PatG, § 9 PatKostG).",
      norms=["§ 84 Abs. 2 PatG", "§ 143 Abs. 3 PatG", "§ 62 PatG", "§ 80 PatG"], cases=["pat_bpatg_syndikusanwalt_kosten"], related=["pat_streitwert", "pat_beschwerde"]),
    # ------------------------------------------------------------------ Verfahren, Fristen, Rechtsmittel
    c("pat_beschwerde", "Beschwerde zum Bundespatentgericht (§§ 73 ff. PatG)", V,
      "Gegen Beschlüsse der Prüfungsstellen und Patentabteilungen findet die Beschwerde zum Patentgericht statt; sie ist binnen eines Monats nach Zustellung beim DPMA einzulegen (§ 73 Abs. 1, 2 PatG), das binnen eines Monats abhelfen kann (Abs. 3). Die Beschwerdegebühr ist innerhalb der Beschwerdefrist zu zahlen, sonst gilt die Beschwerde als nicht eingelegt (§ 6 Abs. 1 S. 2, Abs. 2 PatKostG).",
      "Gebühr 500 EUR gegen Entscheidungen über den Einspruch (Nr. 401 100), 200 EUR in anderen Fällen (Nr. 401 300). Aufschiebende Wirkung (§ 75). Zuständig: Technische Beschwerdesenate (Erteilung, Einspruch), Juristischer Beschwerdesenat (Verfahrensfragen, Kosten, Wiedereinsetzung, Register). Entscheidung in der Sache oder Zurückverweisung (§ 79 Abs. 3); keine neuen Widerrufsgründe von Amts wegen (Ventileinrichtung). Rechtsbeschwerde: § 100.",
      norms=["§ 73 PatG", "§ 74 PatG", "§ 75 PatG", "§ 79 PatG", "§ 80 PatG", "§ 6 Abs. 1 PatKostG", "§ 6 Abs. 2 PatKostG"], cases=["pat_bgh_ventileinrichtung", "pat_bpatg_teilbeschluss"], related=["pat_rechtsbeschwerde", "pat_einspruch", "pat_zahlungsfristen", "pat_wiedereinsetzung"]),
    c("pat_rechtsbeschwerde", "Rechtsbeschwerde zum BGH (§§ 100 ff. PatG)", V,
      "Gegen Beschlüsse der Beschwerdesenate findet die Rechtsbeschwerde zum BGH statt, wenn das Patentgericht sie zugelassen hat (§ 100 Abs. 1, 2 PatG) oder ein absoluter Rechtsbeschwerdegrund vorliegt (§ 100 Abs. 3 PatG: fehlerhafte Besetzung, ausgeschlossener Richter, Verletzung des rechtlichen Gehörs, fehlende Vertretung, Öffentlichkeit, fehlende Gründe); Frist ein Monat, Anwaltszwang (§ 102 PatG).",
      "Der BGH prüft nur Rechtsfragen (§ 105 i.V.m. Revisionsrecht). Versagung des rechtlichen Gehörs (Nr. 3) ist der häufigste Grund der zulassungsfreien Rechtsbeschwerde (Schwingungsdämpfer: Hinweispflicht bei nebengeordneten Ansprüchen). Zulassung bei grundsätzlicher Bedeutung oder zur Rechtsfortbildung.",
      norms=["§ 100 PatG", "§ 101 PatG", "§ 102 PatG", "§ 107 PatG"], cases=["pat_bgh_schwingungsdaempfer", "pat_bgh_leistungshalbleiterbauelement"], related=["pat_beschwerde", "pat_rechtliches_gehoer"]),
    c("pat_rechtliches_gehoer", "Rechtliches Gehör im Patentverfahren", V,
      "Beteiligte müssen Gelegenheit haben, sich zu allen entscheidungserheblichen Tatsachen und Rechtsfragen zu äußern (Art. 103 Abs. 1 GG); das DPMA darf nur aus Gründen zurückweisen, zu denen der Anmelder gehört wurde (§ 48 i.V.m. § 42 Abs. 3 PatG), und das Patentgericht muss auf abweichende Rechtsauffassungen hinweisen.",
      "Verletzung ist absoluter Rechtsbeschwerdegrund (§ 100 Abs. 3 Nr. 3 PatG) und Anhörungsrüge (§ 321a ZPO i.V.m. § 99 Abs. 1 PatG, Gebühr Nr. 403 100). Beispiel: Hinweispflicht, wenn nur ein nebengeordneter Anspruch verteidigt wird (Schwingungsdämpfer); Rückzahlung der Beschwerdegebühr bei Gehörsverstoß des DPMA (§ 80 Abs. 3).",
      norms=["§ 48 PatG", "§ 100 Abs. 3 PatG", "§ 99 Abs. 1 PatG", "§ 80 Abs. 3 PatG"], cases=["pat_bgh_schwingungsdaempfer"], related=["pat_rechtsbeschwerde", "pat_beschwerde"]),
    c("pat_wiedereinsetzung", "Wiedereinsetzung in den vorigen Stand (§ 123 PatG)", V,
      "Wer ohne Verschulden verhindert war, eine Frist einzuhalten, deren Versäumung einen Rechtsnachteil zur Folge hat, wird auf Antrag wieder eingesetzt; der Antrag ist binnen zwei Monaten nach Wegfall des Hindernisses zu stellen, zu begründen und die Handlung nachzuholen, spätestens ein Jahr nach Fristablauf (§ 123 Abs. 1, 2 PatG).",
      "Ausgeschlossen für Einspruchsfrist, Prioritätsfrist und die Nachfrist zur Erfinderbenennung (§ 123 Abs. 1 S. 2; BPatG Mehrfach-Funkgerät). Verschulden des Vertreters wird zugerechnet (§ 85 Abs. 2 ZPO), Büroversehen bei zuverlässigem Personal und Kontrolle nicht. Nach Wiedereinsetzung Zwischenbenutzungsrecht Dritter (§ 123 Abs. 5); der Dritte ist am einseitigen Wiedereinsetzungsverfahren nicht beteiligt (Verdickerpolymer II). Zuständig: Juristischer Beschwerdesenat.",
      norms=["§ 123 PatG"], cases=["pat_bgh_verdickerpolymer_ii", "pat_bpatg_mehrfach_funkgeraet", "pat_bpatg_weiterbehandlung"], related=["pat_weiterbehandlung", "pat_fristen", "pat_laufzeit_jahresgebuehren"]),
    c("pat_weiterbehandlung", "Weiterbehandlung (§ 123a PatG)", V,
      "Ist eine Anmeldung wegen Versäumung einer vom DPMA bestimmten Frist zurückgewiesen worden, wird der Zurückweisungsbeschluss auf Antrag gegenstandslos, wenn der Anmelder binnen eines Monats nach Zustellung die versäumte Handlung nachholt und die Weiterbehandlungsgebühr zahlt (§ 123a PatG); ein Verschulden spielt keine Rolle.",
      "Nur für Anmeldeverfahren und amtsseitig gesetzte Fristen, nicht für gesetzliche Fristen (Prüfungsantrag, Beschwerde) und nicht für Einspruch. Gebühr 100 EUR (Nr. 313 000). Die Monatsfrist ist nicht verlängerbar; Nachholung muss vollständig innerhalb der Frist erfolgen (BPatG Weiterbehandlung, Weiterbehandlung II). Wiedereinsetzung in die Weiterbehandlungsfrist ist möglich.",
      norms=["§ 123a PatG", "§ 6 Abs. 1 PatKostG"], cases=["pat_bpatg_weiterbehandlung", "pat_bpatg_weiterbehandlung_ii"], related=["pat_wiedereinsetzung", "pat_pruefungsverfahren", "pat_fristen"]),
    c("pat_fristen", "Fristen im Patentverfahren (Übersicht)", V,
      "Gesetzliche Fristen: Übersetzung drei Monate (§ 35 Abs. 2), Erfinderbenennung 15 Monate (§ 37), Prioritätserklärung 16 Monate (§ 41), Prüfungsantrag sieben Jahre (§ 44), Einspruch neun Monate (§ 59), Beschwerde und Rechtsbeschwerde ein Monat (§ 73, § 102), Berufung ein Monat plus drei Monate Begründung (§ 110), Wiedereinsetzung zwei Monate/ein Jahr (§ 123), Weiterbehandlung ein Monat (§ 123a); Zahlungsfristen nach §§ 6, 7 PatKostG.",
      "Fristberechnung nach §§ 187 ff. BGB, Fristende an Samstag, Sonntag, Feiertag verschiebt sich (§ 193 BGB, § 222 ZPO). Amtsseitige Fristen sind verlängerbar, gesetzliche nicht. Für Klausuren: Fristbeginn (Zustellung, Anmeldetag, Veröffentlichung), Fristende, Zahlungstag nach der PatKostZV, Rechtsfolge der Versäumung und der Rechtsbehelf (Wiedereinsetzung oder Weiterbehandlung).",
      norms=["§ 35 PatG", "§ 37 PatG", "§ 41 PatG", "§ 44 PatG", "§ 59 PatG", "§ 73 PatG", "§ 110 PatG", "§ 123 PatG", "§ 123a PatG", "§ 6 PatKostG", "§ 7 PatKostG"], cases=[], related=["pat_wiedereinsetzung", "pat_weiterbehandlung", "pat_zahlungsfristen"]),
    c("pat_bpatg_aufbau", "Bundespatentgericht: Aufbau und Senate (§§ 65 ff. PatG)", V,
      "Das Bundespatentgericht in München entscheidet über Beschwerden gegen Beschlüsse des DPMA sowie über Nichtigkeits- und Zwangslizenzklagen (§ 65 PatG). Technische Beschwerdesenate sind mit einem rechtskundigen und zwei technischen Richtern besetzt, Nichtigkeitssenate mit zwei rechtskundigen und drei technischen Richtern, der Juristische Beschwerdesenat mit drei rechtskundigen Richtern (§ 66, § 67 PatG).",
      "Die Entscheidungsdatenbank des BPatG (rund 15.800 Entscheidungen der Nichtigkeits-, Technischen, Juristischen und Gebrauchsmuster-Senate seit 2000 in diesem Korpus) zeigt, welche Vorschriften in der Praxis tragen: §§ 1, 3, 4 (Patentfähigkeit), § 21 (Widerruf), § 59 (Einspruch), § 123 (Wiedereinsetzung), Art. II § 6 IntPatÜG (Nichtigkeit europäischer Patente) und § 6 PatKostG (Zahlungsfristen).",
      norms=["§ 65 PatG", "§ 66 PatG", "§ 67 PatG", "§ 99 PatG"], cases=[], related=["pat_beschwerde", "pat_nichtigkeitsklage", "pat_rechtsbeschwerde"]),
    c("pat_gebrauchsmuster_abzweigung", "Gebrauchsmuster und Abzweigung (Verhältnis zum PatG)", V,
      "Das Gebrauchsmuster ist ein ungeprüftes Schutzrecht für technische Erfindungen außer Verfahren (§ 2 GebrMG) mit zehnjähriger Laufzeit; aus einer Patentanmeldung kann binnen zwei Monaten nach deren Erledigung ein Gebrauchsmuster mit gleichem Zeitrang abgezweigt werden (§ 5 GebrMG, § 145a PatG).",
      "Neuheitsbegriff relativ mit sechsmonatiger Schonfrist (§ 3 GebrMG), erfinderischer Schritt; Schutzhindernisse prüft die Gebrauchsmusterstelle nur nach § 2 GebrMG (Feldmausbekämpfung). Löschungsverfahren beim DPMA (§ 16 GebrMG), Beschwerde zum Gebrauchsmuster-Beschwerdesenat. Gebühren: Anmeldung 30 EUR, Löschungsantrag 300 EUR.",
      norms=["§ 145a PatG"], cases=["pat_bgh_feldmausbekaempfung"], related=["pat_erfindung", "pat_neuheit"]),
    c("pat_gebrauchsmuster", "Gebrauchsmuster: Wesen und Schutzfähigkeit (§§ 1 bis 3 GebrMG)", V,
      "Als Gebrauchsmuster werden Erfindungen geschützt, die neu sind, auf einem erfinderischen Schritt beruhen und gewerblich anwendbar sind (§ 1 Abs. 1 GebrMG); ausgeschlossen sind Verfahren (§ 2 Nr. 3 GebrMG) und biotechnologische Erfindungen. Es wird ohne Prüfung von Neuheit und erfinderischem Schritt eingetragen (§ 8 GebrMG), dauert höchstens zehn Jahre (§ 23 GebrMG) und gibt dieselben Ansprüche wie ein Patent (§ 24 GebrMG).",
      "Der Neuheitsbegriff ist relativ: schriftliche Beschreibungen weltweit, Benutzungen nur im Inland, mit sechsmonatiger Schonfrist für eigene Offenbarungen (§ 3 Abs. 1 GebrMG); der erfinderische Schritt verlangt nach BGH Demonstrationsschrank (X ZB 27/05) dasselbe wie die erfinderische Tätigkeit. Wegen der fehlenden Prüfung trägt der Inhaber im Verletzungsprozess das Risiko; das Verletzungsgericht prüft die Schutzfähigkeit als Einwand (anders als beim Patent). Aufrechterhaltung: Gebühren für das 4. bis 6., 7. und 8., 9. und 10. Jahr.",
      norms=["§ 145a PatG"], cases=["pat_bgh_feldmausbekaempfung"], related=["pat_gebrauchsmuster_abzweigung", "pat_gebrauchsmuster_loeschung", "pat_neuheit", "pat_erfinderische_taetigkeit"]),
    c("pat_gebrauchsmuster_loeschung", "Löschungsverfahren beim Gebrauchsmuster (§§ 15 bis 17 GebrMG)", V,
      "Jedermann kann beim DPMA die Löschung des Gebrauchsmusters beantragen, wenn der Gegenstand nicht schutzfähig ist, bereits aufgrund einer früheren Patent- oder Gebrauchsmusteranmeldung geschützt ist oder über die ursprüngliche Anmeldung hinausgeht (§ 15 Abs. 1 GebrMG); bei widerrechtlicher Entnahme nur der Verletzte (§ 15 Abs. 2 GebrMG). Widerspricht der Inhaber nicht binnen eines Monats, wird gelöscht (§ 17 Abs. 1 GebrMG).",
      "Gebühr 300 EUR (Nr. 323 100), Kosten nach §§ 91 ff. ZPO (§ 17 Abs. 4 GebrMG); Beschwerde zum Gebrauchsmuster-Beschwerdesenat des BPatG (§ 18 GebrMG), Rechtsbeschwerde. Das Löschungsverfahren ersetzt Einspruch und Nichtigkeitsklage des Patentrechts; daneben kann die Schutzunfähigkeit im Verletzungsprozess als Einwand geltend gemacht werden, das Gericht kann nach § 19 GebrMG aussetzen.",
      norms=["§ 145a PatG"], cases=[], related=["pat_gebrauchsmuster", "pat_nichtigkeitsklage", "pat_einspruch"]),
    # ------------------------------------------------------------------ Kosten (PatKostG)
    c("pat_gebuehren", "Gebühren des DPMA und des BPatG (PatKostG, Gebührenverzeichnis)", K,
      "Die Gebühren des DPMA und des BPatG richten sich nach dem Gebührenverzeichnis der Anlage zum PatKostG (§ 2 Abs. 1 PatKostG); im Klageverfahren vor dem BPatG werden Wertgebühren nach dem Streitwert erhoben (§ 2 Abs. 2 PatKostG). Kostenschuldner ist, wer die Amtshandlung beantragt (§ 4 PatKostG).",
      "Patentsachen: Anmeldung 40 EUR elektronisch (Nr. 311 000), Recherche 300 EUR (311 200), Prüfung 350/150 EUR (311 400/311 300), Jahresgebühren 3. Jahr 70 EUR bis 20. Jahr 2 030 EUR (312 030 ff.), Weiterbehandlung 100 EUR (313 000), Einspruch 200 EUR (313 600), Beschwerde 500/200 EUR (401 100/401 300), Nichtigkeitsklage 4,5 Wertgebühren (402 100). Vorbemerkung: elektronische Anmeldung günstiger; Einspruchsgebühr je Einsprechender. Beträge im Verzeichnis prüfen (§ 13: Satz bei Fälligkeit).",
      norms=["§ 2 PatKostG", "§ 4 PatKostG", "Anlage PatKostG"], cases=["pat_bpatg_einspruchsgebuehren_gemeinsam", "pat_bpatg_pruefungsgebuehr_ausscheidung"], related=["pat_faelligkeit", "pat_zahlungsfristen", "pat_jahresgebuehren", "pat_streitwert"]),
    c("pat_faelligkeit", "Fälligkeit der Gebühren (§ 3 PatKostG)", K,
      "Gebühren werden mit Einreichung der Anmeldung, des Antrags oder der Vornahme der Handlung fällig (§ 3 Abs. 1 PatKostG); Jahresgebühren werden jeweils für das folgende Jahr am letzten Tag des Monats fällig, der durch seine Benennung dem Monat des Anmeldetags entspricht (§ 3 Abs. 2 PatKostG).",
      "Beispiel: Anmeldung am 12.3.2024 → dritte Jahresgebühr fällig am 31.3.2026, zuschlagsfrei bis 31.5.2026, mit Zuschlag bis 30.9.2026 (§ 7 Abs. 1). Von der Fälligkeit laufen die Zahlungsfristen des § 6 und § 7. Nationale Gebühr bei PCT-Anmeldungen: Fälligkeit mit Ablauf der 30-Monats-Frist (BPatG Nationale Gebühr). Zahlungstag nach § 2 PatKostZV (Überweisung: Tag des Eingangs, SEPA-Lastschrift: Tag des Mandatseingangs).",
      norms=["§ 3 PatKostG", "§ 5 PatKostG"], cases=["pat_bpatg_nationale_gebuehr_pct"], related=["pat_gebuehren", "pat_zahlungsfristen", "pat_jahresgebuehren"]),
    c("pat_zahlungsfristen", "Zahlungsfristen und Folgen der Nichtzahlung (§ 6 PatKostG)", K,
      "Anmelde-, Prüfungs- und Antragsgebühren sind binnen drei Monaten nach Fälligkeit zu zahlen, Gebühren für Rechtsbehelfe innerhalb der Rechtsbehelfsfrist (§ 6 Abs. 1 PatKostG); bei Nichtzahlung gilt die Anmeldung als zurückgenommen, der Antrag als nicht gestellt und der Rechtsbehelf als nicht erhoben (§ 6 Abs. 2 PatKostG).",
      "Die Dreimonatsfrist gilt auch für die Prüfungsgebühr einer Ausscheidungsanmeldung (BPatG Prüfungsgebühr), nicht für die nationale PCT-Gebühr (BPatG Nationale Gebühr). Für Einspruch und Beschwerde ist die Gebühr binnen der Einspruchs- bzw. Beschwerdefrist zu zahlen, je Einsprechender (BPatG Einspruchsgebühren). Rechtsbehelf gegen die Fiktion: Wiedereinsetzung (§ 123 PatG), bei Anmeldungen auch Weiterbehandlung (§ 123a PatG) nur bei amtsseitigen Fristen. Jahresgebühren: eigene Regelung in § 7.",
      norms=["§ 6 PatKostG"], cases=["pat_bpatg_einspruchsgebuehren_gemeinsam", "pat_bpatg_pruefungsgebuehr_ausscheidung", "pat_bpatg_nationale_gebuehr_pct"], related=["pat_faelligkeit", "pat_jahresgebuehren", "pat_beschwerde", "pat_einspruch", "pat_fristen"]),
    c("pat_jahresgebuehren", "Jahresgebühren: Zahlungsfrist und Verspätungszuschlag (§ 7 PatKostG)", K,
      "Jahresgebühren können bis zum Ablauf des zweiten Monats nach Fälligkeit ohne Zuschlag gezahlt werden; danach bis zum Ablauf des sechsten Monats nach Fälligkeit mit einem Verspätungszuschlag von 50 EUR (§ 7 Abs. 1 PatKostG); wird nicht gezahlt, erlischt das Patent rückwirkend zum Fälligkeitstag (§ 20 Abs. 1 Nr. 3 PatG).",
      "Vorauszahlung bis zu einem Jahr vor Fälligkeit möglich (Abs. 2). Die Frist wird durch Insolvenz nicht unterbrochen (BPatG Sägeblatt). Mit Rechtsgrund gezahlte Jahresgebühren werden nicht zurückgezahlt (BPatG Jahresgebühren, § 10). Nach Erlöschen: Wiedereinsetzung binnen zwei Monaten nach Wegfall des Hindernisses, spätestens ein Jahr nach Ablauf der Zuschlagsfrist (Verdickerpolymer II). Lizenzbereitschaft halbiert die Gebühr (§ 23 PatG). Für europäische Patente Art. II § 7 IntPatÜG.",
      norms=["§ 7 PatKostG", "§ 3 Abs. 2 PatKostG", "§ 10 PatKostG", "§ 17 PatG", "§ 20 Abs. 1 Nr. 3 PatG"], cases=["pat_bpatg_saegeblatt", "pat_bpatg_jahresgebuehren_rueckzahlung", "pat_bgh_verdickerpolymer_ii"], related=["pat_laufzeit_jahresgebuehren", "pat_faelligkeit", "pat_zahlungsfristen", "pat_wiedereinsetzung"]),
    c("pat_kostenrechtsbehelfe", "Kostenansatz, Erinnerung und Rückzahlung (§§ 8 bis 11 PatKostG)", K,
      "Die Kosten werden vom DPMA oder BPatG angesetzt (§ 8 PatKostG); gegen den Kostenansatz sind Erinnerung und Beschwerde gegeben (§ 11 PatKostG). Kosten, die bei richtiger Sachbehandlung nicht entstanden wären, werden nicht erhoben (§ 9 PatKostG); ohne Rechtsgrund gezahlte Gebühren werden zurückgezahlt (§ 10 PatKostG).",
      "Rückzahlung der Beschwerdegebühr aus Billigkeit ist daneben in § 80 Abs. 3 PatG geregelt. Keine Rückzahlung mit Rechtsgrund gezahlter Jahresgebühren, auch bei späterer Nichtigerklärung (BPatG Jahresgebühren). Verjährung vier Jahre (§ 12).",
      norms=["§ 8 PatKostG", "§ 9 PatKostG", "§ 10 PatKostG", "§ 11 PatKostG", "§ 12 PatKostG"], cases=["pat_bpatg_jahresgebuehren_rueckzahlung"], related=["pat_gebuehren", "pat_kostenerstattung"]),
    # ------------------------------------------------------------------ IntPatÜG
    c("pat_ep_validierung", "Europäisches Patent mit Wirkung für Deutschland (Art. II IntPatÜG)", I,
      "Ein vom EPA erteiltes europäisches Patent hat in Deutschland dieselbe Wirkung wie ein nationales Patent (Art. 64 EPÜ); das IntPatÜG regelt Entschädigung (Art. II § 1), Übersetzungen (§§ 2, 3), Nichtigkeit (§ 6), Jahresgebühren (§ 7), Doppelschutz (§§ 8, 18) und Umwandlung (§ 9). Seit dem Londoner Übereinkommen (1.5.2008) entfällt die Übersetzung der Patentschrift (Art. XI § 4).",
      "Für Altpatente mit Erteilungshinweis vor dem 1.5.2008 blieb das Übersetzungserfordernis bestehen (BPatG Ethylenische Hauptketten). Verletzung und Rechtsfolgen nach §§ 9 ff., 139 ff. PatG; Nichtigkeit nach Art. II § 6 vor dem BPatG, sofern nicht das EPG ausschließlich zuständig ist (Art. 32, 83 EPGÜ). Jahresgebühren an das DPMA ab dem Jahr nach dem Erteilungshinweis (Art. II § 7).",
      norms=["Art. II § 1 IntPatÜG", "Art. II § 3 IntPatÜG", "Art. II § 6 IntPatÜG", "Art. II § 7 IntPatÜG", "Art. XI § 4 IntPatÜG"], cases=["pat_bpatg_ethylenische_hauptketten", "pat_bpatg_torasemid"], related=["pat_nichtigkeit_ep", "pat_doppelschutz", "pat_einheitspatent_national", "pat_laufzeit_jahresgebuehren"]),
    c("pat_doppelschutz", "Doppelschutzverbot und Einrede der doppelten Inanspruchnahme (Art. II §§ 8, 18 IntPatÜG)", I,
      "Ein deutsches Patent verliert seine Wirkung, soweit für dieselbe Erfindung desselben Erfinders mit gleichem Zeitrang ein europäisches Patent mit Wirkung für Deutschland erteilt ist (Art. II § 8 IntPatÜG); seit 1.6.2023 gilt das nicht, wenn das europäische Patent dem EPG unterliegt: Dann bleibt der Doppelschutz bestehen, und der Beklagte kann die Einrede der doppelten Inanspruchnahme erheben (Art. II § 18 IntPatÜG).",
      "Doppelschutz ermöglicht die parallele Durchsetzung vor deutschen Gerichten (aus dem deutschen Patent) und dem EPG (aus dem europäischen Patent oder Einheitspatent); die Einrede verhindert, dass derselbe Beklagte wegen derselben Handlung zweimal in Anspruch genommen wird. Bei Opt-out bleibt es beim Doppelschutzverbot des § 8. Prüfung: gleiche Erfindung, gleicher Erfinder, gleicher Zeitrang.",
      norms=["Art. II § 8 IntPatÜG", "Art. II § 18 IntPatÜG"], cases=[], related=["pat_ep_validierung", "pat_einheitspatent_national", "pat_verletzung"]),
    c("pat_einheitspatent_national", "Einheitspatent im nationalen Recht (Art. II §§ 15 bis 20 IntPatÜG)", I,
      "Für das europäische Patent mit einheitlicher Wirkung gelten die Vorschriften über europäische Patente entsprechend, soweit die Verordnung (EU) Nr. 1257/2012 nichts anderes bestimmt; nationale Nichtigkeit, Jahresgebühren an das DPMA, Doppelschutzverbot und Umwandlung sind ausgeschlossen (Art. II § 15 IntPatÜG). Zwangslizenzen erteilt das BPatG (§ 16), Verzicht nur einheitlich (§ 17), Vollstreckung von EPG-Entscheidungen nach der ZPO (§ 19).",
      "Ergänzt die EPatVO (Art. 3, 4, 7) und das EPGÜ (Art. 32, 82) auf nationaler Ebene; die Vorschriften traten mit dem EPGÜ am 1.6.2023 in Kraft. Zusammenspiel: Einheitspatent → EPG ausschließlich zuständig (Art. 32 EPGÜ), deutsches Parallelpatent bleibt (§ 18), Vollstreckung durch deutsche Gerichtsvollzieher mit Klausel des Landgerichts (§ 19).",
      norms=["Art. II § 15 IntPatÜG", "Art. II § 16 IntPatÜG", "Art. II § 17 IntPatÜG", "Art. II § 19 IntPatÜG", "Art. II § 20 IntPatÜG"], cases=[], related=["pat_ep_validierung", "pat_doppelschutz", "pat_zwangslizenz", "upc_einheitspatent"]),
    c("pat_pct_nationale_phase", "PCT-Anmeldung und nationale Phase (Art. III IntPatÜG)", I,
      "Das DPMA ist Anmeldeamt (Art. III § 1 IntPatÜG), Bestimmungsamt (§ 4) und ausgewähltes Amt (§ 6) für internationale Anmeldungen nach dem PCT; für die nationale Phase sind binnen 30 Monaten ab Prioritätstag die Übersetzung einzureichen und die nationale Gebühr zu zahlen (Art. III § 4 Abs. 2 IntPatÜG), sonst gilt die Wirkung der Anmeldung als beendet.",
      "Die nationale Gebühr (Nr. 311 150: 60 EUR) wird mit Ablauf der Frist fällig; § 6 Abs. 1 PatKostG gewährt keine weitere Frist (BPatG Nationale Gebühr). Prüfungsantrag und Jahresgebühren folgen dem PatG. Euro-PCT: Eintritt in die regionale Phase beim EPA (Art. 153 EPÜ, 31 Monate). Entschädigung nach § 33 PatG erst mit deutscher Übersetzung (Art. III § 8).",
      norms=["Art. III § 1 IntPatÜG", "Art. III § 4 IntPatÜG", "Art. III § 6 IntPatÜG", "Art. III § 8 IntPatÜG", "§ 3 Abs. 1 PatKostG"], cases=["pat_bpatg_nationale_gebuehr_pct"], related=["pat_anmeldung", "pat_faelligkeit", "pat_ep_validierung"]),
]
